  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'qm-002',
  'qualitaetsmanagement',
  'qm-grundlagen',
  'cloze',
  null,
  'Ergänze die Aussagen zum Qualitätsbegriff.',
  'Qualität = Erfüllungsgrad der Anforderungen. Daraus folgt eine praktische Konsequenz: Ohne prüfbar formulierte Anforderungen kann man Qualität gar nicht feststellen. Deshalb hängen Anforderungsanalyse und Qualitätssicherung unmittelbar zusammen - und deshalb ist eine unprüfbare Anforderung wie "benutzerfreundlich" ein Qualitätsproblem, bevor die erste Zeile Code geschrieben ist. Ein Produkt, das mehr kann als gefordert, hat nicht mehr Qualität, sondern verschwendet Budget.',
  2,
  ARRAY['qualitätsbegriff']::text[],
  null,
  '{"cloze_text":"Qualität ist der {0}, in dem ein Produkt die festgelegten {1} erfüllt. Maßstab ist der {2}, nicht das Empfinden des Entwicklerteams. Feststellen lässt sich Qualität deshalb nur, wenn die Anforderungen {3} formuliert sind.","gaps":[{"answers":["Grad"],"rationale":"Qualität ist relativ, nicht absolut."},{"answers":["Anforderungen"],"rationale":"Nicht die technisch bestmögliche Ausführung zählt."},{"answers":["Kunde"],"rationale":"Seine Anforderungen sind der Maßstab."},{"answers":["prüfbar"],"rationale":"\"Benutzerfreundlich\" allein lässt sich nicht prüfen."}],"word_bank":["Preis","Fehler","Hersteller","allgemein"]}'::jsonb,
  'current'
)
