insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  've-002',
  'vertraege',
  'vt-urheber',
  'pairs',
  null,
  'Verbinde jedes Lizenzmodell mit seinem Kennzeichen.',
  'Vier Begriffe sauber trennen:
- Freeware: kostenlos, Quellcode geschlossen.
- Open Source: Quellcode offen, oft mit Pflichten (Copyleft).
- Proprietär: kostenpflichtig, Quellcode geschlossen.
- SaaS/Abo: Nutzungsrecht auf Zeit, Betrieb beim Anbieter.
Lizenzmodelle nach Zählweise: pro Gerät, pro benanntem Nutzer, pro gleichzeitigem Nutzer (concurrent), pro CPU/Core, nutzungsabhängig. Volumenlizenzen sind meist, aber nicht immer günstiger als der Einzelkauf.',
  2,
  ARRAY['lizenzen']::text[],
  null,
  '{"pairs":[{"left":"Einzelplatzlizenz","right":"an ein Gerät oder einen Nutzer gebunden"},{"left":"Concurrent-User-Lizenz","right":"begrenzt die gleichzeitigen Nutzer"},{"left":"Volumenlizenz","right":"viele Lizenzen in einem Vertrag"},{"left":"Software-Abonnement (SaaS)","right":"Nutzungsrecht nur für die Laufzeit"},{"left":"Freeware","right":"kostenlos, Quellcode meist geschlossen"},{"left":"Copyleft-Lizenz (z. B. GPL)","right":"Änderungen unter gleicher Lizenz weitergeben"}]}'::jsonb,
  'current'
)
