values (
  'a7-vz-3',
  'vertraege',
  'vt-zustandekommen',
  'table',
  null,
  'Bestimme für jeden Fall die Geschäftsfähigkeit und die Wirksamkeit des Geschäfts.',
  'Unter 7 Jahren: geschäftsunfähig, Erklärungen sind nichtig. 7 bis 17 Jahre: beschränkt geschäftsfähig, Verträge sind bis zur Genehmigung der Eltern schwebend unwirksam - außer beim Taschengeldparagrafen. Ab 18: voll geschäftsfähig.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Fall"},{"text":"Geschäftsfähigkeit"},{"text":"Das Geschäft ist"}],[{"text":"Ein 6-jähriges Kind kauft ein Videospiel für 60 €."},{"gap":{"answers":["geschäftsunfähig"],"options":["geschäftsunfähig","beschränkt geschäftsfähig","voll geschäftsfähig"],"rationale":"Unter 7 Jahren ist man geschäftsunfähig."}},{"gap":{"answers":["nichtig"],"options":["nichtig","wirksam","schwebend unwirksam"],"rationale":"Die Willenserklärung eines Geschäftsunfähigen ist nichtig (§ 105 BGB)."}}],[{"text":"Eine 15-Jährige kauft von ihrem Taschengeld bar eine Maus für 20 €."},{"gap":{"answers":["beschränkt geschäftsfähig"],"options":["beschränkt geschäftsfähig","geschäftsunfähig","voll geschäftsfähig"],"rationale":"Von 7 bis 17 Jahren."}},{"gap":{"answers":["wirksam"],"options":["wirksam","nichtig","schwebend unwirksam"],"rationale":"Taschengeldparagraf (§ 110 BGB): mit eigenen Mitteln sofort bezahlt."}}],[{"text":"Ein 17-Jähriger schließt ohne Wissen der Eltern einen Handyvertrag über 24 Monate."},{"gap":{"answers":["beschränkt geschäftsfähig"],"options":["beschränkt geschäftsfähig","geschäftsunfähig","voll geschäftsfähig"],"rationale":"Von 7 bis 17 Jahren."}},{"gap":{"answers":["schwebend unwirksam"],"options":["schwebend unwirksam","wirksam","nichtig"],"rationale":"Erst die Genehmigung der Eltern macht den Vertrag wirksam (§ 108 BGB)."}}],[{"text":"Eine 19-jährige Auszubildende least ein Notebook."},{"gap":{"answers":["voll geschäftsfähig"],"options":["voll geschäftsfähig","geschäftsunfähig","beschränkt geschäftsfähig"],"rationale":"Ab 18 Jahren."}},{"gap":{"answers":["wirksam"],"options":["wirksam","nichtig","schwebend unwirksam"],"rationale":"Volljährige schließen Verträge ohne Zustimmung anderer."}}]]}'::jsonb,
