insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-pb-1',
  'projektorganisation',
  'p-begriff',
  'marking',
  'Das Autohaus Lindner (35 Beschäftigte) ersetzt seine alte Telefonanlage durch Cloud-Telefonie. Im Projektauftrag und in den Notizen der IT stehen folgende Angaben.',
  'Markiere alle Angaben, die ein Merkmal eines Projekts beschreiben.',
  'Projektmerkmale sind Einmaligkeit, ein klares Ziel, zeitliche Begrenzung, begrenzte Ressourcen und eine eigene Organisation. Angaben zum laufenden Betrieb oder zu Routinetätigkeiten gehören nicht dazu.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Eine solche Umstellung hat das Autohaus noch nie durchgeführt.","is_correct":true,"rationale":"Einmaligkeit bzw. Neuartigkeit - das Kernmerkmal eines Projekts."},{"text":"Die Telefonanlage wird an jedem Werktag von 7 bis 18 Uhr genutzt.","is_correct":false,"rationale":"Beschreibt den laufenden Betrieb, kein Merkmal des Vorhabens."},{"text":"Am 30.09. müssen alle 42 Nebenstellen umgestellt sein.","is_correct":true,"rationale":"Klares Ziel mit festem Endtermin - zeitliche Begrenzung."},{"text":"Für das Vorhaben stehen 18.000 € und 25 Personentage bereit.","is_correct":true,"rationale":"Begrenzte finanzielle und personelle Ressourcen."},{"text":"Der Support setzt jede Woche vergessene Mailbox-PINs zurück.","is_correct":false,"rationale":"Wiederkehrende Routine - eine Linienaufgabe."},{"text":"IT, Verkauf und Werkstatt bilden für die Dauer der Umstellung ein eigenes Team mit Projektleiterin.","is_correct":true,"rationale":"Projektspezifische Organisation auf Zeit."},{"text":"Der Vertrag mit dem bisherigen Anbieter läuft seit 2015.","is_correct":false,"rationale":"Eine Information zur Ausgangslage, kein Projektmerkmal."}],"points":4}'::jsonb,
  'current'
)
