insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-pb-2',
  'projektorganisation',
  'p-begriff',
  'open',
  'Die Zahnarztpraxis Dr. Sommer zieht zum 01.04. in neue Räume. Dein Ausbildungsbetrieb plant dafür Netzwerk, Server und acht Arbeitsplätze neu. Dein Ausbilder sagt: „Das ist ein klassisches Projekt.“',
  'Nenne vier Merkmale, die ein Vorhaben zu einem Projekt machen.',
  'Je Nennung 1 Punkt, höchstens 4 Punkte. Stichworte genügen. Andere fachlich richtige Merkmale wie Komplexität oder Risiko zählen ebenfalls.',
  1,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Einmaligkeit bzw. Neuartigkeit des Vorhabens","points":1,"keywords":["einmalig","neuartig","erstmalig","einzigartig","keine Routine"]},{"text":"Klares, konkretes Ziel","points":1,"keywords":["Ziel","Zielvorgabe","zielgerichtet","Zielsetzung"]},{"text":"Zeitliche Begrenzung: fester Anfang und festes Ende","points":1,"keywords":["zeitlich begrenzt","zeitliche Begrenzung","befristet","Endtermin","Anfang und Ende","Termin"]},{"text":"Begrenzte Ressourcen (Budget, Personal)","points":1,"keywords":["Budget","Ressourcen","Kosten","finanziell","personell"]},{"text":"Eigene, projektspezifische Organisation (Projektleitung, Team)","points":1,"keywords":["Organisation","Projektteam","Projektleitung","eigenes Team"]},{"text":"Komplexität und Risiko","points":1,"keywords":["komplex","Risiko","Unsicherheit","Umfang"]}],"sample_solution":"Ein Projekt ist einmalig bzw. neuartig, hat ein klares Ziel, ist zeitlich begrenzt (fester Anfang und fester Endtermin), verfügt über begrenzte Ressourcen (Budget, Personal) und hat eine eigene Projektorganisation. Hinzu kommen Komplexität und ein höheres Risiko als bei Routineaufgaben."}'::jsonb,
