insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-po-3',
  'projektorganisation',
  'p-organisation',
  'matching',
  'Die Nordfracht AG wickelt mehrere Projekte gleichzeitig ab - jedes in der Form, die zu ihm passt.',
  'Ordne jeder Beschreibung die passende Form der Projektorganisation zu.',
  'Entscheidend sind Größe, Dauer und die Frage, wie viel die Projektleitung zu sagen hat: volle Befugnis (rein), nur fachliche (Matrix) oder keine (Stab/Einfluss).',
  2,
  '{}',
  null,
  '{"buckets":["Reine Projektorganisation","Matrix-Organisation","Stabs-/Einflussorganisation"],"match_items":[{"text":"Vier Kolleginnen überarbeiten in fünf Wochen nebenbei die Vorlagen im Intranet; ein Koordinator hält die Fäden zusammen.","bucket":2,"rationale":"Klein, kurz, nebenbei - eine koordinierende Stelle ohne Weisungsbefugnis genügt."},{"text":"Zwölf Beschäftigte werden für zwei Jahre freigestellt, um ein neues Rechenzentrum aufzubauen.","bucket":0,"rationale":"Groß, lang, in Vollzeit - das Team wird aus der Linie herausgelöst."},{"text":"Eine Netzwerkadministratorin arbeitet zu 30 % im Projekt „WLAN-Ausbau“ und zu 70 % weiter im Betrieb.","bucket":1,"rationale":"Anteilige Mitarbeit mit zwei Vorgesetzten ist typisch für die Matrix."},{"text":"Die Projektleitung entscheidet auch über Urlaub und Beurteilung der Teammitglieder.","bucket":0,"rationale":"Disziplinarische Befugnis hat die Projektleitung nur in der reinen Projektorganisation."},{"text":"Die Projektleitung kann nur empfehlen; entschieden wird in den Fachabteilungen.","bucket":2,"rationale":"Keine Weisungsbefugnis - Kennzeichen der Einflussorganisation."},{"text":"Über die Arbeitsinhalte bestimmt die Projektleitung, über Gehalt und Urlaub der Abteilungsleiter.","bucket":1,"rationale":"Geteilte Weisungsbefugnis: fachlich das Projekt, disziplinarisch die Linie."}],"points":3}'::jsonb,
  'current'
)
