insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-pr-1',
  'projektorganisation',
  'p-rollen',
  'table',
  'Im Projekt „Neue Zeiterfassung“ des Pflegeheims Lindenhof gilt: Die Projektleiterin erstellt den Terminplan selbst; der Auftraggeber verantwortet ihn und entscheidet über die Freigabe; das Projektteam wird vorher nach seinen Aufwänden gefragt. Die Schulungen führt das Team durch, verantwortet werden sie von der Projektleiterin; der Auftraggeber erhält danach nur die Teilnehmerliste.',
  'Trage die RACI-Buchstaben ein (R = führt durch, A = verantwortet und entscheidet, C = wird befragt, I = wird informiert).',
  'RACI: R = Responsible (führt durch), A = Accountable (verantwortet und entscheidet, genau einmal je Aufgabe), C = Consulted (wird vorher befragt), I = Informed (wird danach informiert).',
  2,
  '{}',
  null,
  '{"points":3,"grid":[[{"text":"Aufgabe"},{"text":"Auftraggeber"},{"text":"Projektleitung"},{"text":"Projektteam"}],[{"text":"Terminplan erstellen"},{"gap":{"answers":["A"],"options":["A","R","C","I"],"rationale":"Verantwortet und gibt frei."}},{"gap":{"answers":["R"],"options":["R","A","C","I"],"rationale":"Erstellt den Plan selbst."}},{"gap":{"answers":["C"],"options":["C","R","A","I"],"rationale":"Wird nach den Aufwänden gefragt."}}],[{"text":"Schulungen durchführen"},{"gap":{"answers":["I"],"options":["I","R","A","C"],"rationale":"Erhält nur die Teilnehmerliste."}},{"gap":{"answers":["A"],"options":["A","R","C","I"],"rationale":"Verantwortet die Schulungen."}},{"gap":{"answers":["R"],"options":["R","A","C","I"],"rationale":"Führt die Schulungen durch."}}]]}'::jsonb,
