insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-ps-3',
  'projektorganisation',
  'p-stakeholder',
  'open',
  'Bei der Elektro Wenzel GmbH sollen 25 Monteure ihre Arbeitszeiten künftig per App statt auf Papier erfassen. Mehrere Monteure äußern Bedenken („Kontrolle“, „zu kompliziert“).',
  'Beschreibe zwei Maßnahmen, mit denen die Projektleitung die Akzeptanz bei den Monteuren erhöht.',
  'Je Maßnahme 2 Punkte (Maßnahme und kurze Ausführung), höchstens 4 Punkte. Grundsatz: Betroffene zu Beteiligten machen - geringer Einfluss, hohes Interesse heißt mindestens „informieren“.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Früh und offen informieren: Ziele, Nutzen und Zeitplan erklären, etwa in einer Infoveranstaltung.","points":2,"keywords":["informieren","Information","Infoveranstaltung","Kommunikation","erklären","transparent"]},{"text":"Betroffene beteiligen: Monteure als Testnutzer bzw. Key-User einbinden und ihre Rückmeldungen berücksichtigen.","points":2,"keywords":["beteiligen","einbinden","einbeziehen","Key-User","Pilot","Testnutzer","Feedback"]},{"text":"Schulen und unterstützen: Schulungen, Kurzanleitung und feste Ansprechperson anbieten.","points":2,"keywords":["Schulung","schulen","Training","Anleitung","Ansprechpartner","Support"]},{"text":"Bedenken ernst nehmen: mit dem Betriebsrat regeln, dass die Daten nicht zur Leistungskontrolle genutzt werden.","points":2,"keywords":["Betriebsrat","Betriebsvereinbarung","Leistungskontrolle","Bedenken","Ängste","Sorgen"]}],"sample_solution":"Die Projektleitung informiert früh und offen über Ziele, Nutzen und Zeitplan, etwa in einer Infoveranstaltung. Sie beteiligt die Monteure, zum Beispiel als Testnutzer in einer Pilotphase, und berücksichtigt deren Rückmeldungen. Schulungen und eine feste Ansprechperson nehmen die Sorge, die App sei zu kompliziert; eine Regelung mit dem Betriebsrat schließt Leistungskontrolle aus."}'::jsonb,
  'current'
)
