insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-vw-1',
  'vorgehensmodelle',
  'v-wasserfall',
  'open',
  'Die Gemeinde Altenried lässt eine Software für die Vergabe von Kita-Plätzen entwickeln. Die Gemeinde hat ein Lastenheft geschrieben, das beauftragte Softwarehaus erstellt daraus das Pflichtenheft.',
  'Erläutere den Unterschied zwischen Lastenheft und Pflichtenheft.',
  'Je Aspekt 1 Punkt: Verfasser und Inhalt des Lastenhefts, Verfasser und Inhalt des Pflichtenhefts. Merkhilfe: Lastenheft = Was und Wofür, Pflichtenheft = Wie und Womit.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Das Lastenheft erstellt der Auftraggeber (hier die Gemeinde).","points":1,"keywords":["Auftraggeber","Kunde","Gemeinde"]},{"text":"Das Lastenheft beschreibt, was das System leisten soll und wofür (Anforderungen).","points":1,"keywords":["was","wofür","Anforderungen"]},{"text":"Das Pflichtenheft erstellt der Auftragnehmer (hier das Softwarehaus).","points":1,"keywords":["Auftragnehmer","Softwarehaus","Dienstleister","Lieferant"]},{"text":"Das Pflichtenheft beschreibt, wie und womit die Anforderungen umgesetzt werden.","points":1,"keywords":["wie","womit","Umsetzung","umgesetzt","Lösung"]}],"sample_solution":"Das Lastenheft schreibt der Auftraggeber. Es beschreibt, was das System leisten soll und wofür - also die Anforderungen. Das Pflichtenheft schreibt der Auftragnehmer. Es beschreibt, wie und womit er die Anforderungen umsetzt, und wird vom Auftraggeber freigegeben."}'::jsonb,
  'current'
)
