insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-vw-2',
  'vorgehensmodelle',
  'v-wasserfall',
  'numeric',
  'Im Wasserfallprojekt „Lagerverwaltung“ ist das Pflichtenheft freigegeben. Der Kunde stellt einen Change Request für eine zusätzliche Etikettendruck-Funktion. Das Softwarehaus schätzt: 3 Tage Entwurf zu 720 € je Tag, 5 Tage Implementierung zu 640 € je Tag und 2 Tage Test zu 560 € je Tag. Auf die Summe kommt ein Zuschlag von 10 % für das Projektmanagement.',
  'Berechne die Kosten des Change Requests.',
  'Entwurf: 3 × 720 € = 2.160 €
Implementierung: 5 × 640 € = 3.200 €
Test: 2 × 560 € = 1.120 €
Summe: 2.160 € + 3.200 € + 1.120 € = 6.480 €
Zuschlag: 6.480 € × 0,10 = 648 €
Kosten des Change Requests: 6.480 € + 648 € = 7.128 €.',
  2,
  '{}',
  null,
  '{"answer":7128.0,"tolerance":0.0,"unit":"€","points":4}'::jsonb,
  'current'
)
