insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-vw-3',
  'vorgehensmodelle',
  'v-wasserfall',
  'marking',
  'Ein Softwarehaus entwickelt zum Festpreis eine Auftragsverwaltung nach dem Wasserfallmodell. Im Projekttagebuch stehen diese Einträge.',
  'Markiere alle Einträge, die dem Wasserfallmodell widersprechen.',
  'Der Wasserfall ist sequenziell und dokumentgetrieben: Jede Phase endet mit einem freigegebenen Ergebnis, Änderungen laufen über Change Requests, lauffähige Software entsteht erst am Ende.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Die Implementierung beginnt, obwohl der Entwurf noch nicht freigegeben ist.","is_correct":true,"rationale":"Eine Phase beginnt erst, wenn das Ergebnis der vorherigen freigegeben ist."},{"text":"Das Pflichtenheft wird vom Kunden unterschrieben, bevor der Entwurf startet.","is_correct":false,"rationale":"Genau so vorgesehen: Das freigegebene Dokument ist die Grundlage der nächsten Phase."},{"text":"Ein neuer Kundenwunsch wird ohne Bewertung direkt eingebaut.","is_correct":true,"rationale":"Änderungen laufen über einen Change Request mit Bewertung von Termin und Kosten."},{"text":"Die Entwickler testen ihre Module schon während der Implementierung.","is_correct":false,"rationale":"Modultests bei der Implementierung sind üblich; die Testphase prüft danach das Gesamtsystem."},{"text":"Der Kunde erhält alle zwei Wochen ein lauffähiges Teilprodukt und priorisiert danach neu.","is_correct":true,"rationale":"Das ist das Vorgehen von Scrum - im Wasserfall gibt es lauffähige Software erst am Ende."},{"text":"Am Ende der Testphase steht ein Testprotokoll.","is_correct":false,"rationale":"Jede Phase endet mit einem dokumentierten Ergebnis."}],"points":3}'::jsonb,
