insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-va-2',
  'vorgehensmodelle',
  'v-auswahl',
  'table',
  'Ein Softwarehaus erstellt für seine neuen Auszubildenden eine Übersicht der beiden Vorgehensmodelle.',
  'Vervollständige den Vergleich.',
  'Wasserfall: vollständig vorab geplant, Anforderungen fest im Pflichtenheft, Ergebnis am Ende, Umfang fest. Scrum: Detailplanung je Sprint, veränderliches Product Backlog, nutzbares Increment nach jedem Sprint, Zeit und Kosten fest.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Merkmal"},{"text":"Wasserfall"},{"text":"Scrum"}],[{"text":"Planung"},{"gap":{"answers":["vollständig vorab"],"options":["vollständig vorab","im Detail je Sprint","gar nicht"]}},{"gap":{"answers":["im Detail je Sprint"],"options":["im Detail je Sprint","vollständig vorab","gar nicht"]}}],[{"text":"Anforderungen"},{"gap":{"answers":["fest im Pflichtenheft"],"options":["fest im Pflichtenheft","veränderlich im Backlog","nicht festgehalten"]}},{"gap":{"answers":["veränderlich im Backlog"],"options":["veränderlich im Backlog","fest im Pflichtenheft","nicht festgehalten"]}}],[{"text":"Nutzbares Ergebnis"},{"gap":{"answers":["am Projektende"],"options":["am Projektende","nach jedem Sprint","nach jedem Daily"]}},{"gap":{"answers":["nach jedem Sprint"],"options":["nach jedem Sprint","am Projektende","nach jedem Daily"]}}],[{"text":"Fest im magischen Dreieck"},{"gap":{"answers":["Umfang"],"options":["Umfang","Zeit und Kosten","nichts"]}},{"gap":{"answers":["Zeit und Kosten"],"options":["Zeit und Kosten","Umfang","nichts"]}}]]}'::jsonb,
