insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-sm-1',
  'agil_scrum',
  's-manifest',
  'marking',
  'Ein international besetztes Entwicklungsteam der Medisoft GmbH hat sich Arbeitsregeln gegeben und an die Bürowand gehängt.',
  'Markiere alle Regeln, die den Werten und Prinzipien des agilen Manifests widersprechen.',
  'Das Manifest verlangt frühe und regelmäßige Lieferung, Offenheit für Änderungen und funktionierende Software als Fortschrittsmaß. Dokumentation ist nicht verboten - links vor rechts, nicht links statt rechts.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"We deliver the software once, after 12 months, when everything is finished.","is_correct":true,"rationale":"Widerspricht dem Prinzip, funktionierende Software früh und regelmäßig zu liefern."},{"text":"We talk to each other every day instead of only writing tickets.","is_correct":false,"rationale":"Passt: Individuen und Interaktionen, direkte Gespräche."},{"text":"Requirements are frozen after the first week; later changes are rejected.","is_correct":true,"rationale":"Widerspricht „Reagieren auf Veränderung“ - Änderungen sind auch spät willkommen."},{"text":"Our customer sees the product every two weeks and gives feedback.","is_correct":false,"rationale":"Passt: Zusammenarbeit mit dem Kunden."},{"text":"Progress is measured by the number of pages in the specification.","is_correct":true,"rationale":"Das wichtigste Fortschrittsmaß ist funktionierende Software, nicht Papier."},{"text":"After each iteration we discuss how to work better.","is_correct":false,"rationale":"Passt: regelmäßig reflektieren und das Verhalten anpassen."},{"text":"We document what is needed to operate the software.","is_correct":false,"rationale":"Passt: Dokumentation bleibt wertvoll, sie ist nur nachrangig."}],"points":3}'::jsonb,
  'current'
)
