insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-sm-3',
  'agil_scrum',
  's-manifest',
  'open',
  'Die Webagentur Kliq will agil arbeiten. Der Geschäftsführer bittet dich, dem Team die Grundlage zu erklären: das agile Manifest.',
  'Nenne die vier Werte des agilen Manifests (jeweils die Seite, die höher geschätzt wird).',
  'Je Wert 1 Punkt. Die rechte Seite bleibt wertvoll - die linke wird nur höher geschätzt. Das Manifest von 2001 umfasst vier Werte und zwölf Prinzipien.',
  1,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Individuen und Interaktionen (mehr als Prozesse und Werkzeuge)","points":1,"keywords":["Individuen","Interaktionen","Menschen"]},{"text":"Funktionierende Software (mehr als umfassende Dokumentation)","points":1,"keywords":["funktionierende Software","lauffähige Software","funktionierendes Produkt","Software"]},{"text":"Zusammenarbeit mit dem Kunden (mehr als Vertragsverhandlung)","points":1,"keywords":["Kunden","Kunde","Kundenzusammenarbeit"]},{"text":"Reagieren auf Veränderung (mehr als das Befolgen eines Plans)","points":1,"keywords":["Veränderung","Änderungen","reagieren","flexibel"]}],"sample_solution":"Individuen und Interaktionen sind wichtiger als Prozesse und Werkzeuge. Funktionierende Software ist wichtiger als umfassende Dokumentation. Zusammenarbeit mit dem Kunden ist wichtiger als Vertragsverhandlung. Reagieren auf Veränderung ist wichtiger als das Befolgen eines Plans."}'::jsonb,
  'current'
)
on conflict (id) do update set
