insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-sr-1',
  'agil_scrum',
  's-rollen',
  'table',
  'Das Fintech-Unternehmen Paylane arbeitet mit Scrum. Im englischen Team-Handbuch steht:',
  'Welche Scrum-Verantwortlichkeit gehört jeweils dazu? Vervollständige die Tabelle.',
  'Maria ordnet das Product Backlog nach Wert - Product Owner. Tom sorgt für wirksame Events und beseitigt Hindernisse (impediments) - Scrum Master. Ali, Jana und Chen bauen das Produkt, planen ihren Sprint selbst und halten die Definition of Done ein - Developers.',
  2,
  '{}',
  null,
  '{"code":"Team handbook - who does what\n\nMaria decides which backlog item is most\nvaluable and in which order the items are built.\n\nTom makes sure the Scrum events take place,\nkeeps them within the timebox and helps to\nremove impediments.\n\nAli, Jana and Chen build the product. They plan\ntheir own work for the sprint and make sure\nevery item meets the Definition of Done.","points":3,"grid":[[{"text":"Person oder Aufgabe"},{"text":"Verantwortlichkeit"}],[{"text":"Maria"},{"gap":{"answers":["Product Owner"],"options":["Product Owner","Scrum Master","Developers"]}}],[{"text":"Tom"},{"gap":{"answers":["Scrum Master"],"options":["Scrum Master","Product Owner","Developers"]}}],[{"text":"Ali, Jana und Chen"},{"gap":{"answers":["Developers"],"options":["Developers","Product Owner","Scrum Master"]}}],[{"text":"Formuliert das Produktziel"},{"gap":{"answers":["Product Owner"],"options":["Product Owner","Scrum Master","Developers"]}}],[{"text":"Erstellt den Plan im Sprint Backlog"},{"gap":{"answers":["Developers"],"options":["Developers","Product Owner","Scrum Master"]}}],[{"text":"Coacht das Team im Selbstmanagement"},{"gap":{"answers":["Scrum Master"],"options":["Scrum Master","Product Owner","Developers"]}}]]}'::jsonb,
