insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i1-sr-2',
  'agil_scrum',
  's-rollen',
  'open',
  'Die Stadtwerke Lahntal entwickeln mit einem Scrum Team eine Kunden-App. Frau Demir aus dem Vertrieb übernimmt die Verantwortlichkeit Product Owner.',
  'Beschreibe zwei Aufgaben, die Frau Demir als Product Owner hat.',
  'Je Aufgabe 2 Punkte, höchstens 4 Punkte. Der Product Owner ist eine Person, kein Gremium, und verantwortet den Wert des Produkts.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Sie formuliert das Produktziel und macht es allen verständlich.","points":2,"keywords":["Produktziel","Product Goal","Vision"]},{"text":"Sie pflegt das Product Backlog: Einträge erstellen und verständlich beschreiben.","points":2,"keywords":["Product Backlog","Backlog pflegen","Einträge","User Stories"]},{"text":"Sie ordnet die Einträge des Product Backlogs nach ihrem Wert (Priorisierung).","points":2,"keywords":["priorisieren","Priorisierung","ordnet","Reihenfolge"]},{"text":"Sie vertritt die Interessen der Stakeholder und verantwortet den Wert des Produkts.","points":2,"keywords":["Stakeholder","Wert","Kunden","Nutzen"]},{"text":"Nur sie darf einen Sprint abbrechen, wenn das Sprintziel hinfällig geworden ist.","points":2,"keywords":["abbrechen","Abbruch","Sprint abbrechen"]}],"sample_solution":"Frau Demir formuliert das Produktziel und macht es dem Team und den Stakeholdern verständlich. Sie pflegt das Product Backlog und ordnet seine Einträge nach ihrem Wert - sie entscheidet also, was als Nächstes gebaut wird. Dabei vertritt sie die Interessen der Stakeholder."}'::jsonb,
