insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-kk-2',
  'kommunikation',
  'k-kunde',
  'open',
  'Bei der Kessler & Brandt IT-Systemhaus GmbH trifft am Montagmorgen die Beschwerde einer Kundin ein. Seit dem Umzug ihrer Postfächer funktionieren drei Dinge nicht mehr.',
  'Beschreibe zwei Schritte, mit denen du professionell auf diese Beschwerde reagierst.',
  'Je beschriebenem Schritt 2 Punkte, höchstens 4. Beschwerdebehandlung: zuhören, Verständnis zeigen, Sachverhalt klären, Lösung mit Termin anbieten, umsetzen und nachfassen. Wichtig: den Rückrufwunsch (before 4 pm = vor 16 Uhr) einhalten.',
  2,
  '{}',
  null,
  '{"code":"... We lose time every day.\nPlease call me before 4 pm today.\n\nKind regards\nSarah Miller, Office Manager","points":4,"criteria":[{"text":"Wie gewünscht noch heute vor 16 Uhr zurückrufen und die Probleme mit Fragen klären.","points":2,"keywords":["zurückrufen","Rückruf","anrufen","16 Uhr","Telefon"]},{"text":"Verständnis zeigen und sich für die Unannehmlichkeiten entschuldigen.","points":2,"keywords":["Verständnis","entschuldigen","bedauern","ernst nehmen"]},{"text":"Ticket anlegen, priorisieren und eine Lösung mit Termin zusagen.","points":2,"keywords":["Ticket","priorisieren","Lösung","Termin","zusagen"]},{"text":"Nach der Behebung nachfassen und die Ursache dokumentieren.","points":2,"keywords":["nachfassen","dokumentieren","Ursache","bestätigen"]}],"sample_solution":"Ich rufe die Kundin wie gewünscht noch heute vor 16 Uhr zurück, zeige Verständnis für den Ärger und kläre die drei Probleme mit gezielten Fragen. Danach lege ich ein Ticket mit hoher Priorität an, nenne ihr einen verbindlichen Termin für die Lösung und frage nach der Behebung nach, ob alles wieder funktioniert."}'::jsonb,
  'current'
