insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-kk-3',
  'kommunikation',
  'k-kunde',
  'open',
  'Im Webshop der Grünwerk Gartenbedarf GmbH bleiben Kundenbeschwerden über verspätete Lieferungen seit Wochen unbeantwortet. In einem Bewertungsportal häufen sich Ein-Sterne-Bewertungen.',
  'Erläutere zwei wirtschaftliche Folgen, die dem Unternehmen dadurch drohen.',
  'Je erläuterter Folge 2 Punkte, höchstens 4. Unbeantwortete Beschwerden kosten doppelt: durch Imageverlust nach außen und durch Abwanderung der bestehenden Kunden. Ein Beschwerdemanagement ist deshalb auch wirtschaftlich sinnvoll.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Imageverlust: Schlechte Bewertungen schrecken mögliche Neukunden ab.","points":2,"keywords":["Image","Bewertung","Reputation","Ansehen","schlechter Ruf"]},{"text":"Kunden wandern zur Konkurrenz ab, der Umsatz sinkt.","points":2,"keywords":["abwandern","Umsatz","Konkurrenz","wechseln","Kunden verlieren"]},{"text":"Stammkunden bestellen nicht wieder und empfehlen den Shop nicht weiter.","points":2,"keywords":["weiterempfehlen","Stammkunden","Empfehlung","Folgeaufträge"]},{"text":"Neue Kunden zu gewinnen kostet mehr (Werbung, Rabatte) als bestehende zu halten.","points":2,"keywords":["Neukunden","Werbung","Werbekosten","Akquise"]}],"sample_solution":"Erstens droht ein Imageverlust: Die schlechten Bewertungen sind öffentlich und schrecken neue Kunden ab. Zweitens wandern verärgerte Kunden zu Wettbewerbern ab - der Umsatz sinkt, und Weiterempfehlungen bleiben aus. Verlorene Kunden zurückzugewinnen kostet zusätzlich Geld für Werbung und Rabatte."}'::jsonb,
  'current'
)
