insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-tt-1',
  'teamarbeit',
  'te-phasen',
  'table',
  'Bei der Pixelhafen Medien GmbH führt ein Team aus fünf Personen das neue Ticketsystem ein. Die Projektleiterin notiert über mehrere Wochen ihre Beobachtungen.',
  'Trage zu jeder Beobachtung die Teamphase nach Tuckman und die passende Aufgabe der Leitung ein.',
  'Forming: Orientierung - die Leitung gibt Ziele und Struktur vor. Storming: Machtkämpfe - die Leitung moderiert. Norming: Regeln entstehen - die Leitung hält sie fest. Performing: Das Team arbeitet eingespielt - die Leitung gibt Freiraum.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Beobachtung"},{"text":"Phase"},{"text":"Aufgabe der Leitung"}],[{"text":"Alle sind höflich und warten ab."},{"gap":{"answers":["Forming"],"options":["Forming","Storming","Norming","Performing"]}},{"gap":{"answers":["Ziele und Aufgaben erklären"],"options":["Ziele und Aufgaben erklären","Konflikte moderieren","Regeln festhalten","Freiraum geben"]}}],[{"text":"Zwei streiten, wessen Konzept gilt."},{"gap":{"answers":["Storming"],"options":["Storming","Forming","Norming","Performing"]}},{"gap":{"answers":["Konflikte moderieren"],"options":["Konflikte moderieren","Ziele und Aufgaben erklären","Regeln festhalten","Freiraum geben"]}}],[{"text":"Das Team legt fest, wie Tickets benannt werden."},{"gap":{"answers":["Norming"],"options":["Norming","Forming","Storming","Performing"]}},{"gap":{"answers":["Regeln festhalten"],"options":["Regeln festhalten","Ziele und Aufgaben erklären","Konflikte moderieren","Freiraum geben"]}}],[{"text":"Die Arbeit läuft selbstständig und zügig."},{"gap":{"answers":["Performing"],"options":["Performing","Forming","Storming","Norming"]}},{"gap":{"answers":["Freiraum geben"],"options":["Freiraum geben","Ziele und Aufgaben erklären","Konflikte moderieren","Regeln festhalten"]}}]]}'::jsonb,
  'current'
)
