insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-tf-2',
  'teamarbeit',
  'te-feedback',
  'open',
  'Deine Kollegin in der IT der Elbtal Logistik AG hat in dieser Woche zweimal Handscanner ausgegeben, ohne sie in die Inventarliste einzutragen. Heute wurde deshalb ein Gerät eine Stunde lang gesucht.',
  'Formuliere ein Feedback an die Kollegin nach der WWW-Methode (Wahrnehmung, Wirkung, Wunsch).',
  'Je Teil 1 Punkt: Wahrnehmung (konkret, ohne „immer“ und ohne Bewertung der Person), Wirkung (was daraus folgte) und Wunsch (was sich ändern soll). Alles als Ich-Botschaft.',
  2,
  '{}',
  null,
  '{"criteria":[{"text":"Wahrnehmung: konkrete Beobachtung ohne Wertung („Mir ist aufgefallen, dass zweimal der Eintrag in der Inventarliste fehlte“).","points":1,"keywords":["aufgefallen","beobachtet","gesehen","bemerkt","wahrgenommen","festgestellt"]},{"text":"Wirkung: Folge der Beobachtung („Dadurch haben wir heute eine Stunde nach einem Gerät gesucht“).","points":1,"keywords":["dadurch","deshalb","deswegen","führt dazu","Folge","gesucht"]},{"text":"Wunsch: konkrete Bitte für die Zukunft („Ich wünsche mir, dass du jede Ausgabe sofort einträgst“).","points":1,"keywords":["wünsche","bitte","Wunsch","künftig","in Zukunft","möchte"]}],"sample_solution":"„Mir ist aufgefallen, dass diese Woche zweimal ein Handscanner ausgegeben wurde, ohne dass er in der Inventarliste steht. Dadurch haben wir heute eine Stunde nach einem Gerät gesucht. Ich wünsche mir, dass du jede Ausgabe sofort einträgst.“"}'::jsonb,
  'current'
)
