insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-tf-3',
  'teamarbeit',
  'te-feedback',
  'open',
  'Bei der Pixelhafen Medien GmbH hat ein Entwickler versehentlich die Live-Website eines Kunden überschrieben und den Fehler erst nach zwei Tagen gemeldet - aus Angst vor Ärger. Die Geschäftsführung will die Fehlerkultur verbessern.',
  'Erläutere zwei Vorteile einer offenen Fehlerkultur für die Agentur.',
  'Je erläutertem Vorteil 2 Punkte, höchstens 4. In einer guten Fehlerkultur gelten Fehler als Lernchance: Es wird nach Ursachen gefragt, nicht nach Schuldigen. Vertuschte Fehler werden dagegen größer.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Fehler werden sofort gemeldet, der Schaden bleibt kleiner.","points":2,"keywords":["früh","sofort","Schaden","rechtzeitig","schnell gemeldet"]},{"text":"Aus Fehlern wird gelernt (Lessons Learned), sie wiederholen sich nicht.","points":2,"keywords":["lernen","Lessons Learned","wiederholen","gelernt","Lernchance"]},{"text":"Ursachen werden gesucht und Abläufe verbessert, die Qualität steigt.","points":2,"keywords":["Ursache","Prozess","Ablauf","Qualität","verbessern"]},{"text":"Weniger Angst und mehr Vertrauen im Team.","points":2,"keywords":["Angst","Vertrauen","Zusammenarbeit","Betriebsklima"]}],"sample_solution":"Wenn niemand Angst vor Schuldzuweisungen haben muss, werden Fehler sofort gemeldet - die Website wäre nach Minuten statt nach zwei Tagen wiederhergestellt worden, der Schaden wäre kleiner. Außerdem wird nach der Ursache gesucht, etwa nach einer fehlenden Freigabe vor dem Einspielen. So lernt das ganze Team daraus und der Fehler wiederholt sich nicht."}'::jsonb,
  'current'
)
