insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-tk-1',
  'teamarbeit',
  'te-konflikte',
  'cloze',
  'Zwei Schichtleiter der Elbtal Logistik AG streiten seit Monaten über die Verteilung der Handscanner. Inzwischen suchen beide Verbündete in ihren Teams und reden schlecht übereinander.',
  'Ergänze die Angaben zum Eskalationsmodell nach Glasl.',
  'Glasl: 9 Stufen in 3 Phasen. Stufe 1-3 (win-win) lösen die Beteiligten noch selbst. Stufe 4-6 (win-lose) brauchen meist einen neutralen Dritten. Stufe 7-9 (lose-lose) lassen sich nur noch durch einen Machteingriff von außen stoppen.',
  3,
  '{}',
  null,
  '{"points":5,"cloze_text":"Glasl beschreibt {0} Eskalationsstufen in {1} Hauptphasen. Wer Verbündete sucht, steht auf Stufe 4 (Images und Koalitionen) und damit in der Phase {2}. In dieser Phase braucht es meist {3}. In der letzten Phase, {4}, nehmen beide sogar eigenen Schaden in Kauf.","gaps":[{"answers":["9"],"numeric":true,"rationale":"Von „Verhärtung“ bis „gemeinsam in den Abgrund“."},{"answers":["3"],"numeric":true,"rationale":"win-win, win-lose und lose-lose mit je drei Stufen."},{"answers":["win-lose"],"options":["win-lose","win-win","lose-lose"],"rationale":"Stufe 4 bis 6: Einer soll gewinnen, der andere verlieren."},{"answers":["einen neutralen Dritten"],"options":["einen neutralen Dritten","mehr Zeit","eine Abmahnung"],"rationale":"Etwa eine Moderation oder Mediation."},{"answers":["lose-lose"],"options":["lose-lose","win-win","win-lose"],"rationale":"Stufe 7 bis 9: Hauptsache, der andere verliert mehr."}]}'::jsonb,
  'current'
)
