insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-tk-2',
  'teamarbeit',
  'te-konflikte',
  'open',
  'In der IT-Abteilung der Grünwerk Gartenbedarf GmbH beanspruchen zwei Kollegen denselben Testserver und sprechen kaum noch miteinander. Die Abteilungsleiterin lädt beide zu einem Konfliktgespräch ein.',
  'Beschreibe zwei Schritte, mit denen das Konfliktgespräch zu einer tragfähigen Lösung führt.',
  'Je beschriebenem Schritt 2 Punkte, höchstens 4. Ein Konfliktgespräch läuft so: Sichtweisen anhören, Interessen klären, Lösungen sammeln, Vereinbarung treffen und später überprüfen. Ziel ist der Konsens, nicht ein fauler Kompromiss.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Beide schildern nacheinander ihre Sichtweise, ohne unterbrochen zu werden.","points":2,"keywords":["Sichtweise","schildern","ausreden","Standpunkt","anhören","zuhören"]},{"text":"Die Interessen hinter den Forderungen klären (Wozu wird der Server wann gebraucht?).","points":2,"keywords":["Interesse","Bedürfnis","wozu","Hintergrund","warum"]},{"text":"Gemeinsam Lösungen sammeln und eine auswählen, die beide mittragen (Konsens).","points":2,"keywords":["Lösung","Konsens","gemeinsam","Vorschläge","Optionen"]},{"text":"Die Vereinbarung festhalten und später überprüfen.","points":2,"keywords":["Vereinbarung","festhalten","überprüfen","schriftlich","kontrollieren"]}],"sample_solution":"Zuerst schildern beide nacheinander ihre Sicht, ohne unterbrochen zu werden - die Abteilungsleiterin moderiert. Danach klärt sie die Interessen: Wozu und wann braucht jeder den Server? Auf dieser Grundlage sammeln alle gemeinsam Lösungen, etwa einen zweiten virtuellen Testserver, und halten die Vereinbarung fest."}'::jsonb,
  'current'
)
