insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-ve-3',
  'verhandlung',
  've-einwaende',
  'open',
  'Ein Filialleiter der Grünwerk Gartenbedarf GmbH lehnt die neuen Kassen-Tablets ab: „Die sind viel zu kompliziert für meine Leute.“',
  'Beschreibe zwei Methoden der Einwandbehandlung und formuliere jeweils eine passende Antwort.',
  'Je Methode mit passender Antwort 2 Punkte, höchstens 4. Methoden: Rückfrage (Hintergrund klären), Ja-aber (zustimmen und ergänzen), Bumerang (Einwand wird zum Argument), Referenz (zufriedene Anwender nennen). Nie direkt widersprechen.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Rückfrage: „Was genau erscheint Ihnen kompliziert?“ - klärt, was hinter dem Einwand steckt.","points":2,"keywords":["Rückfrage","Gegenfrage","nachfragen","was genau"]},{"text":"Ja-aber-Methode: erst zustimmen, dann ein Gegenargument ergänzen („Ja, die Umstellung braucht etwas Übung - dafür entfällt das Nachtragen am Abend“).","points":2,"keywords":["Ja-aber","zustimmen","Gegenargument"]},{"text":"Bumerang-Methode: den Einwand zum Argument machen („Gerade weil Ihre Leute wenig Zeit haben, hilft die geführte Bedienung“).","points":2,"keywords":["Bumerang","gerade weil","gerade deshalb"]},{"text":"Referenzmethode: auf gute Erfahrungen anderer verweisen („Die Filiale Kassel arbeitet seit drei Monaten problemlos damit“).","points":2,"keywords":["Referenz","andere Filiale","Erfahrungen","andere Kunden"]}],"sample_solution":"Rückfrage: „Was genau erscheint Ihnen kompliziert?“ - so erfahre ich, ob es um die Bedienung oder um die Einarbeitung geht. Bumerang-Methode: „Gerade weil Ihre Leute wenig Zeit haben, hilft das Tablet: Es führt Schritt für Schritt durch den Kassiervorgang.“"}'::jsonb,
  'current'
)
