insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-pq-3',
  'praesentation',
  'pr-quellen',
  'marking',
  'Für eine Kundenpräsentation der Kessler & Brandt IT-Systemhaus GmbH hast du ein Quellenverzeichnis angelegt. Vor der Abgabe prüfst du die Einträge.',
  'Markiere alle Einträge, die als Quellenangabe nicht ausreichen.',
  'Eine Internetquelle braucht Autor oder Herausgeber, Jahr, Titel, URL und Abrufdatum - Webseiten ändern sich. Bei Büchern gehören Auflage, Ort und Verlag dazu. Suchmaschinen sind nur der Weg zur Quelle, nicht die Quelle selbst.',
  2,
