  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-pa-2',
  'praesentation',
  'pr-angebot',
  'table',
  'Auf der Eingangsrechnung der Bürotechnik Nordhessen GmbH an die Grünwerk Gartenbedarf GmbH stehen mehrere Datumsangaben. Heute ist der 12.03.2026.',
  'Ordne jedem Datum den kaufmännischen Vorgang zu und gib an, ob er bereits stattgefunden hat.',
  'Bereits stattgefunden haben Bestellung (02.03.), Lieferung (09.03.) und Rechnungsstellung (10.03.). Skontofrist (20.03.) und Zahlungsziel (09.04.) sind Fristen in der Zukunft. Wird nach „stattgefundenen Vorgängen“ gefragt, zählen nur die ersten drei.',
  2,
  '{}',
  null,
  '{"code":"Rechnung Nr. R-10482\nRechnungsdatum:        10.03.2026\nIhre Bestellung vom:   02.03.2026\nLieferdatum:           09.03.2026\nZahlbar bis 09.04.2026 ohne Abzug,\nbis 20.03.2026 mit 2 % Skonto.","points":5,"grid":[[{"text":"Datum"},{"text":"Vorgang"},{"text":"schon erfolgt?"}],[{"text":"02.03.2026"},{"gap":{"answers":["Bestellung"],"options":["Bestellung","Lieferung","Rechnungsstellung","Ende der Skontofrist","Ende des Zahlungsziels"]}},{"gap":{"answers":["ja"],"options":["ja","nein","nicht erkennbar"]}}],[{"text":"09.03.2026"},{"gap":{"answers":["Lieferung"],"options":["Lieferung","Bestellung","Rechnungsstellung","Ende der Skontofrist","Ende des Zahlungsziels"]}},{"gap":{"answers":["ja"],"options":["ja","nein","nicht erkennbar"]}}],[{"text":"10.03.2026"},{"gap":{"answers":["Rechnungsstellung"],"options":["Rechnungsstellung","Bestellung","Lieferung","Ende der Skontofrist","Ende des Zahlungsziels"]}},{"gap":{"answers":["ja"],"options":["ja","nein","nicht erkennbar"]}}],[{"text":"20.03.2026"},{"gap":{"answers":["Ende der Skontofrist"],"options":["Ende der Skontofrist","Bestellung","Lieferung","Rechnungsstellung","Ende des Zahlungsziels"]}},{"gap":{"answers":["nein"],"options":["nein","ja","nicht erkennbar"]}}],[{"text":"09.04.2026"},{"gap":{"answers":["Ende des Zahlungsziels"],"options":["Ende des Zahlungsziels","Bestellung","Lieferung","Rechnungsstellung","Ende der Skontofrist"]}},{"gap":{"answers":["nein"],"options":["nein","ja","nicht erkennbar"]}}]]}'::jsonb,
