insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i2-pa-3',
  'praesentation',
  'pr-angebot',
  'table',
  'Die Bürotechnik Nordhessen GmbH schickt der Grünwerk Gartenbedarf GmbH eine korrigierte Rechnung. Zahlungsbedingung: 30 Tage ohne Abzug, bei Zahlung innerhalb von 10 Tagen 2 % Skonto vom Rechnungsbetrag.',
  'Vervollständige die Rechnung. Runde kaufmännisch auf zwei Nachkommastellen.',
  'Netto 19 %: 6 × 189 € + 6 × 129 € + 12 × 7,50 € = 1.134 € + 774 € + 90 € = 1.998,00 €; USt 19 % = 379,62 €. Netto 7 %: 2 × 40 € = 80,00 €; USt 7 % = 5,60 €. Rechnungsbetrag: 1.998,00 + 379,62 + 80,00 + 5,60 = 2.463,22 €. Skonto: 2 % von 2.463,22 € = 49,2644 → 49,26 €. Überweisung: 2.463,22 € − 49,26 € = 2.413,96 €.',
  3,
  '{}',
  null,
  '{"table":[["Position","Menge","Einzelpreis netto","USt"],["Monitor 27 Zoll","6","189,00 €","19 %"],["Dockingstation","6","129,00 €","19 %"],["HDMI-Kabel 2 m","12","7,50 €","19 %"],["Fachbuch Netzwerktechnik","2","40,00 €","7 %"]],"points":7,"grid":[[{"text":"Zeile"},{"text":"Betrag in €"}],[{"text":"Nettobetrag zu 19 %"},{"gap":{"answers":["1998"],"numeric":true,"tolerance":0.01,"rationale":"1.134 + 774 + 90"}}],[{"text":"+ 19 % Umsatzsteuer"},{"gap":{"answers":["379.62"],"numeric":true,"tolerance":0.01,"rationale":"1.998 × 0,19"}}],[{"text":"Nettobetrag zu 7 %"},{"gap":{"answers":["80"],"numeric":true,"tolerance":0.01,"rationale":"2 × 40"}}],[{"text":"+ 7 % Umsatzsteuer"},{"gap":{"answers":["5.6"],"numeric":true,"tolerance":0.01,"rationale":"80 × 0,07"}}],[{"text":"= Rechnungsbetrag (brutto)"},{"gap":{"answers":["2463.22"],"numeric":true,"tolerance":0.01,"rationale":"1.998 + 379,62 + 80 + 5,60"}}],[{"text":"- 2 % Skonto"},{"gap":{"answers":["49.26"],"numeric":true,"tolerance":0.01,"rationale":"2.463,22 × 0,02 = 49,2644"}}],[{"text":"= Überweisungsbetrag"},{"gap":{"answers":["2413.96"],"numeric":true,"tolerance":0.01,"rationale":"2.463,22 − 49,26"}}]]}'::jsonb,
