insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i3-hi-2',
  'hardware',
  'h-schnittstellen',
  'open',
  'An einem Arbeitsplatz sollen drei Monitore betrieben werden. Der PC hat nur einen freien DisplayPort-Ausgang. Der Hersteller empfiehlt Daisy Chaining.',
  'Beschreibe das Daisy Chaining von Monitoren und nenne zwei technische Voraussetzungen.',
  'Bewertung: 2 Punkte für die Beschreibung, je 1 Punkt für eine Voraussetzung - höchstens 4 Punkte. HDMI eignet sich nicht für eine Monitorkette.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Die Monitore werden hintereinander verbunden: vom PC zum ersten Monitor, von dort zum nächsten - nur ein Kabel führt zum PC","points":2,"keywords":["hintereinander","in Reihe","Kette","von Monitor zu Monitor","nacheinander"]},{"text":"Der PC-Ausgang muss Multi-Stream Transport (MST) unterstützen: DisplayPort ab 1.2 oder Thunderbolt","points":1,"keywords":["MST","Multi-Stream","DisplayPort 1.2","Thunderbolt"]},{"text":"Die Monitore (außer dem letzten) brauchen einen DisplayPort-Ausgang zum Weiterreichen","points":1,"keywords":["DisplayPort-Ausgang","DP OUT","Ausgang am Monitor","weiterreichen","durchschleifen"]},{"text":"Die Datenrate des einen Ausgangs muss für alle Bilder zusammen reichen","points":1,"keywords":["Bandbreite","Datenrate","Auflösung","teilen"]}],"sample_solution":"Beim Daisy Chaining werden die Monitore in Reihe geschaltet: Ein Kabel führt vom PC zum ersten Monitor, von dessen Ausgang geht es zum zweiten und von dort zum dritten. Voraussetzungen: Der Ausgang des PCs (DisplayPort ab 1.2 oder Thunderbolt) und die Monitore müssen Multi-Stream Transport unterstützen, und die Monitore in der Kette brauchen einen DisplayPort-Ausgang. Die Datenrate des einen Ausgangs muss für alle Bilder genügen."}'::jsonb,
  'current'
)
