insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ld-1',
  'anforderungen',
  'af-dokumente',
  'open',
  'Ein Sanitätshaus möchte seine Lagerverwaltung ablösen und holt dafür Angebote ein. Die Geschäftsführerin fragt, wozu sie neben dem Lastenheft später noch ein Pflichtenheft braucht.',
  'Beschreibe den Unterschied zwischen Lastenheft und Pflichtenheft. (4 P.)',
  'Je Dokument 1 Punkt für den Verfasser und 1 Punkt für den Inhalt. Merkhilfe: Lastenheft = Was und Wofür (Auftraggeber), Pflichtenheft = Wie und Womit (Auftragnehmer).',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Lastenheft: vom Auftraggeber erstellt","points":1,"keywords":["auftraggeber","kunde","kundin","besteller"]},{"text":"Lastenheft: beschreibt, was die Lösung leisten soll (Anforderungen, lösungsneutral)","points":1,"keywords":["was","anforderungen","lösungsneutral","ziele"]},{"text":"Pflichtenheft: vom Auftragnehmer erstellt","points":1,"keywords":["auftragnehmer","dienstleister","anbieter","lieferant"]},{"text":"Pflichtenheft: beschreibt, wie und womit die Anforderungen umgesetzt werden","points":1,"keywords":["wie","womit","umsetzung","lösungskonzept","technisch"]}],"sample_solution":"Das Lastenheft schreibt der Auftraggeber. Es beschreibt lösungsneutral, was das System leisten soll und wofür. Das Pflichtenheft schreibt der Auftragnehmer. Es beschreibt, wie und womit er die Anforderungen umsetzt, und wird nach der Genehmigung zur Grundlage der Abnahme."}'::jsonb,
  'current'
)
