insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-de-1',
  'datenmodellierung',
  'dm-erm',
  'matching',
  'Die Kessler & Brandt IT-Systemhaus GmbH will die Wartung von Kundengeräten in einer Datenbank erfassen. Techniker warten Geräte; ein Techniker wartet im Lauf der Zeit viele Geräte, ein Gerät wird von verschiedenen Technikern gewartet. Zu jeder Wartung werden das Datum und die Dauer festgehalten.',
  'Ordne jedes Attribut dem Element des ER-Modells zu, an dem es eingetragen wird.',
  'Attribute, die nur für die Kombination zweier Entitäten einen Sinn ergeben (Wartungsdatum, Dauer), gehören an die Beziehung. Alles, was eine Entität allein beschreibt, steht an der Entität. In der Prüfung kostet genau diese Unterscheidung regelmäßig Punkte.',
  3,
  '{}',
  null,
  '{"diagram":{"type":"erm","entitaeten":[{"name":"Techniker","attribute":[],"schluessel":[]},{"name":"Gerät","attribute":[],"schluessel":[]}],"beziehungen":[{"a":"Techniker","name":"wartet","b":"Gerät","kard_a":"n","kard_b":"m"}]},"buckets":["Techniker","Gerät","Beziehung „wartet“"],"match_items":[{"text":"Seriennummer","bucket":1,"rationale":"Kennzeichnet genau ein Gerät."},{"text":"Wartungsdatum","bucket":2,"rationale":"Gehört zur einzelnen Wartung, also zur Kombination aus Techniker und Gerät."},{"text":"Personalnummer","bucket":0,"rationale":"Kennzeichnet genau einen Techniker."},{"text":"Hersteller","bucket":1,"rationale":"Eigenschaft des Geräts."},{"text":"Dauer in Minuten","bucket":2,"rationale":"Jede Wartung dauert unterschiedlich lang - weder Techniker noch Gerät haben „eine“ Dauer."},{"text":"Qualifikation","bucket":0,"rationale":"Eigenschaft des Technikers."},{"text":"Nachname","bucket":0,"rationale":"Eigenschaft des Technikers."},{"text":"Standort beim Kunden","bucket":1,"rationale":"Eigenschaft des Geräts."}],"points":4}'::jsonb,
  'current'
)
