insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-de-2',
  'datenmodellierung',
  'dm-erm',
  'cloze',
  'Die Grünwerk Gartenbedarf GmbH hat für ihren Webshop das folgende ER-Modell in Chen-Notation erstellt.',
  'Ergänze die Aussagen zum ER-Modell.',
  'Chen-Notation lesen: Rechtecke sind Entitätstypen, die Raute ist die Beziehung, unterstrichen ist der Primärschlüssel. Die Kardinalität liest man immer in beide Richtungen: Ein Kunde gibt n Bestellungen auf, eine Bestellung gehört zu 1 Kunden (1:n). Bestellung und Artikel stehen in einer n:m-Beziehung.',
  2,
  '{}',
  null,
  '{"diagram":{"type":"erm","entitaeten":[{"name":"Kunde","attribute":["KundenNr","Name","Ort"],"schluessel":["KundenNr"]},{"name":"Bestellung","attribute":["BestellNr","Datum"],"schluessel":["BestellNr"]},{"name":"Artikel","attribute":["ArtikelNr","Bezeichnung","Preis"],"schluessel":["ArtikelNr"]}],"beziehungen":[{"a":"Kunde","name":"gibt auf","b":"Bestellung","kard_a":"1","kard_b":"n"},{"a":"Bestellung","name":"enthält","b":"Artikel","kard_a":"n","kard_b":"m"}]},"points":5,"cloze_text":"Das Modell enthält {0} Entitätstypen. Der Primärschlüssel von Artikel ist {1}. Eine Bestellung gehört zu {2} Kunden. Ein Artikel kann in {3} Bestellungen vorkommen. Die Beziehung „enthält“ hat die Kardinalität {4}.","gaps":[{"answers":["3"],"numeric":true,"rationale":"Kunde, Bestellung und Artikel."},{"answers":["ArtikelNr"],"options":["ArtikelNr","Bezeichnung","Preis","BestellNr"],"rationale":"Das unterstrichene Attribut ist der Primärschlüssel."},{"answers":["genau einem"],"options":["genau einem","beliebig vielen","keinem"],"rationale":"Auf der Seite von Kunde steht die 1."},{"answers":["beliebig vielen"],"options":["beliebig vielen","genau einer","höchstens einer"],"rationale":"Auf der Seite der Bestellung steht n."},{"answers":["n:m"],"options":["n:m","1:n","1:1"],"rationale":"Auf beiden Seiten steht „viele“."}]}'::jsonb,
  'current'
)
