insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-de-3',
  'datenmodellierung',
  'dm-erm',
  'open',
  'Im Lager der Elbtal Logistik AG werden Artikel auf Lagerplätzen eingelagert. Ein Artikel kann auf mehreren Lagerplätzen liegen, auf einem Lagerplatz können mehrere Artikel liegen. Ein Kollege möchte das Attribut „Menge“ beim Entitätstyp Artikel eintragen.',
  'Erläutere, warum das Attribut „Menge“ an die Beziehung zwischen Artikel und Lagerplatz gehört und nicht an den Entitätstyp Artikel.',
  'Je Aspekt 2 Punkte: Abhängigkeit von beiden Entitäten und die Folge eines falschen Eintrags. Andere fachlich richtige Formulierungen zählen ebenso. Bei der Umsetzung in Tabellen landet die Menge in der Zwischentabelle.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Die Menge hängt von der Kombination aus Artikel und Lagerplatz ab - sie beschreibt, wie viel eines Artikels auf einem bestimmten Platz liegt.","points":2,"keywords":["Kombination","beiden","je Lagerplatz","pro Lagerplatz","bestimmten Platz"]},{"text":"Beim Artikel könnte nur ein einziger Wert stehen - die Mengen der einzelnen Lagerplätze ließen sich nicht unterscheiden.","points":2,"keywords":["nur ein Wert","einziger Wert","mehrere Lagerplätze","nicht unterscheiden","Gesamtmenge"]}],"sample_solution":"Die Menge ist keine Eigenschaft des Artikels allein: Derselbe Artikel liegt auf mehreren Lagerplätzen in unterschiedlicher Stückzahl. Die Menge gehört deshalb zur Kombination aus Artikel und Lagerplatz, also an die Beziehung. Stünde sie beim Artikel, gäbe es nur einen einzigen Wert, und die Bestände der einzelnen Plätze ließen sich nicht festhalten."}'::jsonb,
  'current'
)
on conflict (id) do update set
