insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dk-3',
  'datenmodellierung',
  'dm-kardinalitaet',
  'open',
  'Die Grünwerk Gartenbedarf GmbH bezieht Artikel von Lieferanten. Ein Lieferant liefert viele Artikel, derselbe Artikel kann von mehreren Lieferanten bezogen werden. Eine Kollegin schlägt vor, in der Tabelle Artikel einfach die Spalte LieferantNr zu ergänzen.',
  'Erläutere, warum dieser Vorschlag die Beziehung nicht abbilden kann, und beschreibe die richtige Umsetzung im relationalen Modell.',
  '2 Punkte für die Begründung (eine Spalte = nur ein Lieferant, also 1:n), 2 Punkte für die Zwischentabelle mit beiden Fremdschlüsseln. Mehrere Spalten Lieferant1, Lieferant2 wären ebenfalls falsch: Sie verletzen die 1NF.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Mit einer Spalte LieferantNr in Artikel kann jeder Artikel nur genau einen Lieferanten haben - das wäre 1:n statt n:m.","points":2,"keywords":["nur einen Lieferanten","ein Lieferant","1:n","nur einer","einzigen Lieferanten"]},{"text":"Richtig ist eine Zwischentabelle mit ArtikelNr und LieferantNr als Fremdschlüsseln (zusammen Primärschlüssel).","points":2,"keywords":["Zwischentabelle","Verknüpfungstabelle","Beziehungstabelle","Hilfstabelle","dritte Tabelle"]}],"sample_solution":"Eine einzelne Fremdschlüsselspalte LieferantNr in Artikel kann pro Artikel nur einen Lieferanten aufnehmen. Damit wäre nur eine 1:n-Beziehung abgebildet, verlangt ist aber n:m. Richtig ist eine Zwischentabelle, z. B. Lieferbeziehung, mit den Fremdschlüsseln ArtikelNr und LieferantNr, die gemeinsam den Primärschlüssel bilden. So entstehen zwei 1:n-Beziehungen."}'::jsonb,
  'current'
)
