  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dl-1',
  'datenmodellierung',
  'dm-schluessel',
  'marking',
  'Die Datenbank des Grünwerk-Webshops besteht aus den folgenden Tabellen. Unterstrichen wären in der Dokumentation nur die Primärschlüssel - die Fremdschlüssel sind noch nicht gekennzeichnet.',
  'Markiere alle Spalten, die Fremdschlüssel sind.',
  'Ein Fremdschlüssel ist eine Spalte, die auf den Primärschlüssel einer anderen Tabelle verweist. In der Zwischentabelle Position sind BestellNr und ArtikelNr beides: gemeinsam Primärschlüssel und einzeln Fremdschlüssel.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Kunde.KundenNr","is_correct":false,"rationale":"Primärschlüssel der Tabelle Kunde."},{"text":"Bestellung.KundenNr","is_correct":true,"rationale":"Verweist auf den Primärschlüssel von Kunde."},{"text":"Bestellung.Datum","is_correct":false,"rationale":"Beschreibendes Attribut ohne Schlüsselrolle."},{"text":"Artikel.LieferantNr","is_correct":true,"rationale":"Verweist auf den Primärschlüssel von Lieferant."},{"text":"Position.BestellNr","is_correct":true,"rationale":"Teil des Primärschlüssels und zugleich Fremdschlüssel auf Bestellung."},{"text":"Position.ArtikelNr","is_correct":true,"rationale":"Teil des Primärschlüssels und zugleich Fremdschlüssel auf Artikel."},{"text":"Position.Menge","is_correct":false,"rationale":"Attribut der Beziehung, kein Schlüssel."},{"text":"Lieferant.LieferantNr","is_correct":false,"rationale":"Primärschlüssel der Tabelle Lieferant."}],"table":[["Tabelle","Spalten"],["Kunde","KundenNr, Name, Ort"],["Bestellung","BestellNr, Datum, KundenNr"],["Artikel","ArtikelNr, Bezeichnung, LieferantNr"],["Position","BestellNr, ArtikelNr, Menge"],["Lieferant","LieferantNr, Firma"]],"points":4,"mono":true}'::jsonb,
