insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dl-2',
  'datenmodellierung',
  'dm-schluessel',
  'marking',
  'In der Tabelle Kunde gibt es genau die Kundennummern K1, K2 und K3. In die Tabelle Bestellung (BestellNr, Datum, KundenNr) sollen die folgenden Datensätze importiert werden. BestellNr ist Primärschlüssel, KundenNr Fremdschlüssel auf Kunde; die referenzielle Integrität ist aktiv.',
  'Markiere alle Datensätze, die die Datenbank ablehnt.',
  'Drei Regeln greifen: Der Primärschlüssel ist eindeutig (B101 doppelt) und nie leer, und jeder Fremdschlüsselwert muss als Primärschlüssel in der referenzierten Tabelle existieren (K7 fehlt). Wiederholte Fremdschlüsselwerte sind dagegen normal.',
  3,
  '{}',
  null,
  '{"choices":[{"text":"B101 | 02.03. | K1","is_correct":false,"rationale":"Neue BestellNr, vorhandener Kunde."},{"text":"B102 | 02.03. | K1","is_correct":false,"rationale":"Derselbe Kunde darf mehrfach bestellen - Fremdschlüssel dürfen sich wiederholen."},{"text":"B103 | 03.03. | K7","is_correct":true,"rationale":"K7 gibt es in Kunde nicht - Verstoß gegen die referenzielle Integrität."},{"text":"B101 | 04.03. | K2","is_correct":true,"rationale":"Die BestellNr B101 ist schon vergeben - ein Primärschlüssel muss eindeutig sein."},{"text":"B104 | 04.03. | K3","is_correct":false,"rationale":"Neue BestellNr, vorhandener Kunde."},{"text":"(leer) | 05.03. | K2","is_correct":true,"rationale":"Ein Primärschlüssel darf nicht leer sein."}],"points":3,"mono":true}'::jsonb,
  'current'
)
