insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dl-3',
  'datenmodellierung',
  'dm-schluessel',
  'open',
  'Die Steuerkanzlei Albers & Partner fragt, wozu die Tabellen Mandant (MandantNr, Name) und Vorgang (VorgangNr, Betreff, MandantNr) Schlüssel brauchen.',
  'Beschreibe am Beispiel die Aufgabe des Primärschlüssels und die Aufgabe des Fremdschlüssels.',
  'Je Schlüssel 2 Punkte: Aussage plus Bezug zum Beispiel. Primärschlüssel = eindeutige Identifikation, Fremdschlüssel = Verweis auf den Primärschlüssel einer anderen Tabelle. Stichworte genügen.',
  1,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Primärschlüssel (MandantNr in Mandant, VorgangNr in Vorgang): identifiziert jeden Datensatz eindeutig.","points":2,"keywords":["eindeutig","identifiziert","Identifikation","unverwechselbar","einmalig"]},{"text":"Fremdschlüssel (MandantNr in Vorgang): verweist auf den Primärschlüssel der Tabelle Mandant und verknüpft so die Tabellen.","points":2,"keywords":["verweist","Verweis","verknüpft","Verknüpfung","Beziehung","referenziert"]}],"sample_solution":"Der Primärschlüssel identifiziert jeden Datensatz einer Tabelle eindeutig: Über die MandantNr wird genau ein Mandant, über die VorgangNr genau ein Vorgang angesprochen. Der Fremdschlüssel MandantNr in der Tabelle Vorgang verweist auf den Primärschlüssel der Tabelle Mandant und verknüpft so jeden Vorgang mit seinem Mandanten."}'::jsonb,
  'current'
)
