insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dl-4',
  'datenmodellierung',
  'dm-schluessel',
  'marking',
  'In einer englischen Fachzeitschrift steht ein kurzer Beitrag über relationale Datenbanken.',
  'Markiere alle Aussagen, die sich dem Text entnehmen lassen.',
  'Der Text nennt vier Aussagen: Primärschlüssel eindeutig und nie leer, oft eine vom System vergebene Nummer (weil sich Namen und E-Mail-Adressen ändern), Fremdschlüssel speichert den Primärschlüssel einer anderen Tabelle, die Verknüpfung vermeidet doppelte Speicherung. Nur werten, was wirklich im Text steht.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"choices":[{"text":"Der Wert eines Primärschlüssels darf nicht leer sein.","is_correct":true,"rationale":"„must never be empty“."},{"text":"Viele Unternehmen verwenden eine vom System erzeugte Nummer als Schlüssel.","is_correct":true,"rationale":"„a simple number that is created by the system“."},{"text":"E-Mail-Adressen sind als Primärschlüssel besonders gut geeignet.","is_correct":false,"rationale":"Im Gegenteil: Der Text nennt sie als Beispiel für Werte, die sich ändern können."},{"text":"Ein Fremdschlüssel enthält den Primärschlüssel einer anderen Tabelle.","is_correct":true,"rationale":"„stores the primary key of another table“."},{"text":"Jede Tabelle braucht mindestens einen Fremdschlüssel.","is_correct":false,"rationale":"Verlangt wird nur ein Primärschlüssel für jede Tabelle."},{"text":"Durch die Verknüpfung müssen dieselben Daten nicht doppelt gespeichert werden.","is_correct":true,"rationale":"„avoids storing the same data twice“."},{"text":"Fremdschlüssel müssen eindeutig sein.","is_correct":false,"rationale":"Das steht nicht im Text - eindeutig sein muss der Primärschlüssel."}],"code":"In a relational database every\ntable needs a primary key. Its\nvalue must be unique and must\nnever be empty. Many companies\nuse a simple number that is\ncreated by the system, because\nnames or e-mail addresses can\nchange. A foreign key stores\nthe primary key of another\ntable. This link keeps related\ndata together and avoids\nstoring the same data twice.","points":4}'::jsonb,
  'current'
)
