  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dl-5',
  'datenmodellierung',
  'dm-schluessel',
  'cloze',
  'Du ergänzt das Glossar im Wiki der IT-Abteilung um den Eintrag „Schlüssel in relationalen Datenbanken“.',
  'Setze die passenden Begriffe ein.',
  'Primärschlüssel = eindeutige Identifikation, Fremdschlüssel = Verweis auf einen Primärschlüssel. Ein zusammengesetzter Schlüssel besteht aus mehreren Spalten, ein künstlicher Schlüssel (Surrogatschlüssel) hat keine fachliche Bedeutung. Die referenzielle Integrität verhindert Verweise ins Leere.',
  1,
  '{}',
  null,
  '{"points":5,"cloze_text":"Ein {0} identifiziert jeden Datensatz einer Tabelle eindeutig. Ein {1} verweist auf den Primärschlüssel einer anderen Tabelle. Besteht ein Schlüssel aus mehreren Spalten, heißt er {2}. Eine vom System vergebene Nummer ohne fachliche Bedeutung ist ein {3} Schlüssel. Dass jeder Fremdschlüsselwert als Primärschlüssel vorhanden sein muss, nennt man {4}.","gaps":[{"answers":["Primärschlüssel"]},{"answers":["Fremdschlüssel"]},{"answers":["zusammengesetzt"]},{"answers":["künstlicher"]},{"answers":["referenzielle Integrität"]}],"word_bank":["Alternativschlüssel","Redundanz","atomar","natürlicher"]}'::jsonb,
  'current'
)
