insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dl-6',
  'datenmodellierung',
  'dm-schluessel',
  'table',
  'Für die Datenbank der Pixelhafen Medien GmbH sind die Primärschlüssel festzulegen.',
  'Wähle für jede Tabelle den geeigneten Primärschlüssel.',
  'Ein Primärschlüssel ist eindeutig, nie leer und stabil. RaumNr und RechnungsNr erfüllen das. In der Zwischentabelle Projektmitarbeit ist erst die Kombination ProjektNr + PersNr eindeutig. Namen und Telefonnummern können doppelt vorkommen oder sich ändern - dann wird ein künstlicher Schlüssel ergänzt. KundenNr in Rechnung ist ein Fremdschlüssel und wiederholt sich.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Tabelle (Spalten)"},{"text":"Primärschlüssel"}],[{"text":"Raum (RaumNr, Etage, Sitzplätze)"},{"gap":{"answers":["RaumNr"],"options":["RaumNr","Etage","Etage + Sitzplätze"]}}],[{"text":"Projektmitarbeit (ProjektNr, PersNr, Rolle) - jede Person ist je Projekt einmal eingetragen"},{"gap":{"answers":["ProjektNr + PersNr"],"options":["ProjektNr + PersNr","ProjektNr","PersNr","Rolle"]}}],[{"text":"Ansprechpartner (Vorname, Nachname, Firma, Telefon)"},{"gap":{"answers":["künstliche Nummer ergänzen"],"options":["künstliche Nummer ergänzen","Nachname","Vorname + Nachname","Telefon"]}}],[{"text":"Rechnung (RechnungsNr, Datum, Betrag, KundenNr)"},{"gap":{"answers":["RechnungsNr"],"options":["RechnungsNr","KundenNr","Datum + Betrag"]}}]]}'::jsonb,
