insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-dn-1',
  'datenmodellierung',
  'dm-normalisierung',
  'marking',
  'Die Grünwerk Gartenbedarf GmbH führt ihre Bestellungen bisher in einer einzigen Tabelle. Die Kundin Yilmaz (K2) zieht von Kassel nach Köln um.',
  'Markiere alle Zeilen, in denen der Ort geändert werden muss, damit die Daten widerspruchsfrei bleiben.',
  'Der Ort der Kundin ist redundant in drei Zeilen gespeichert. Wird nur eine davon geändert, widersprechen sich die Daten - eine Änderungsanomalie. In normalisierter Form stünde der Ort genau einmal in einer Tabelle Kunde.',
  1,
  '{}',
  null,
  '{"choices":[{"text":"Zeile 1","is_correct":false,"rationale":"Kunde Brandt (K1) wohnt weiter in Kassel."},{"text":"Zeile 2","is_correct":true,"rationale":"Bestellung der Kundin Yilmaz (K2)."},{"text":"Zeile 3","is_correct":false,"rationale":"Kunde Nowak (K3) ist nicht betroffen."},{"text":"Zeile 4","is_correct":true,"rationale":"Bestellung der Kundin Yilmaz (K2)."},{"text":"Zeile 5","is_correct":false,"rationale":"Kunde Brandt wohnt zwar in Kassel, zieht aber nicht um."},{"text":"Zeile 6","is_correct":true,"rationale":"Bestellung der Kundin Yilmaz (K2)."}],"table":[["Zeile","BestellNr","KundenNr","Name","Ort","Artikel"],["1","B101","K1","Brandt","Kassel","Spaten"],["2","B102","K2","Yilmaz","Kassel","Rasenmäher"],["3","B103","K3","Nowak","Fulda","Gießkanne"],["4","B104","K2","Yilmaz","Kassel","Gartenschlauch"],["5","B105","K1","Brandt","Kassel","Harke"],["6","B106","K2","Yilmaz","Kassel","Spaten"]],"points":3}'::jsonb,
