insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-wa-3',
  'web_internet',
  'wi-aufruf',
  'matching',
  'Die Pixelhafen Medien GmbH sortiert Kundenanfragen danach, ob eine statische Website genügt oder eine dynamische nötig ist.',
  'Ordne jede Anforderung der passenden Art von Website zu.',
  'Statisch reicht, wenn alle Besucher denselben, selten geänderten Inhalt sehen. Sobald der Inhalt vom Nutzer, von Eingaben oder von aktuellen Daten abhängt (Anmeldung, Warenkorb, Suche), muss ein Programm auf dem Server die Seite beim Aufruf erzeugen.',
  2,
  '{}',
  null,
  '{"buckets":["statische Website genügt","dynamische Website nötig"],"match_items":[{"text":"Warenkorb mit Bestellung","bucket":1,"rationale":"Der Inhalt hängt vom einzelnen Besucher ab."},{"text":"Visitenkarte eines Malerbetriebs mit Anschrift und Öffnungszeiten","bucket":0,"rationale":"Der Inhalt ist für alle gleich und ändert sich selten."},{"text":"Kundenbereich mit Anmeldung und eigenen Rechnungen","bucket":1,"rationale":"Die Seite wird je Nutzer aus der Datenbank erzeugt."},{"text":"Einmalige Einladungsseite zu einem Firmenjubiläum","bucket":0,"rationale":"Fester Inhalt ohne Eingaben."},{"text":"Suche über den aktuellen Lagerbestand","bucket":1,"rationale":"Das Ergebnis hängt von der Eingabe und den aktuellen Daten ab."},{"text":"Online-Handbuch, das zweimal im Jahr neu erzeugt wird","bucket":0,"rationale":"Fertige Dateien reichen aus."}],"points":3}'::jsonb,
