insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-wt-4',
  'web_internet',
  'wi-html',
  'open',
  'Auf den alten Seiten eines Kunden der Pixelhafen Medien GmbH stehen Farben und Schriftgrößen direkt in jedem einzelnen HTML-Element. Beim Relaunch soll die Gestaltung in eine zentrale CSS-Datei ausgelagert werden.',
  'Erläutere zwei Vorteile der Trennung von Struktur (HTML) und Gestaltung (CSS).',
  'Je erläutertem Vorteil 2 Punkte, verlangt sind zwei. Kern: HTML sagt, was etwas ist, CSS sagt, wie es aussieht - so wird Gestaltung einmal zentral festgelegt statt in jedem Element.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Zentrale Pflege: Eine Änderung in der CSS-Datei wirkt auf alle Seiten - weniger Aufwand.","points":2,"keywords":["zentral","eine Stelle","alle Seiten","einmal ändern","Pflege","Wartung"]},{"text":"Einheitliches Erscheinungsbild auf allen Seiten.","points":2,"keywords":["einheitlich","konsistent","gleiches Aussehen","Corporate Design"]},{"text":"Übersichtlicheres HTML und bessere Zugänglichkeit: Die Struktur bleibt für Screenreader und Suchmaschinen klar.","points":2,"keywords":["übersichtlich","Screenreader","barrierefrei","Suchmaschinen","lesbar"]},{"text":"Verschiedene Darstellungen für dieselbe Struktur, z. B. für Handy, Desktop oder Druck.","points":2,"keywords":["responsiv","responsive","Handy","Druck","Geräte","Media Query"]}],"sample_solution":"Erstens lässt sich die Gestaltung zentral pflegen: Eine Änderung in der CSS-Datei, etwa einer Farbe, wirkt sofort auf allen Seiten. Zweitens sehen alle Seiten einheitlich aus. Außerdem bleibt das HTML übersichtlich und seine Struktur für Screenreader und Suchmaschinen klar, und dieselbe Seite kann für Handy, Desktop oder Druck unterschiedlich dargestellt werden."}'::jsonb,
  'current'
)
