insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-wf-1',
  'web_internet',
  'wi-barrierefrei',
  'open',
  'Der Webshop der Grünwerk Gartenbedarf GmbH muss nach dem Barrierefreiheitsstärkungsgesetz barrierefrei sein. Bei einer Prüfung fällt auf: Produktbilder haben keine Beschreibung, hellgraue Schrift steht auf weißem Grund, das Menü lässt sich nur mit der Maus öffnen und Produktvideos haben keinen Text.',
  'Beschreibe drei Maßnahmen, mit denen der Webshop barrierefreier wird.',
  'Je beschriebener Maßnahme 2 Punkte, höchstens 6 - verlangt sind drei, die Situation bietet vier Ansatzpunkte. Die Maßnahmen folgen den WCAG-Prinzipien wahrnehmbar (Alt-Text, Kontrast, Untertitel) und bedienbar (Tastatur).',
  2,
  '{}',
  null,
  '{"points":6,"criteria":[{"text":"Produktbilder erhalten aussagekräftige Alternativtexte, die Screenreader vorlesen.","points":2,"keywords":["Alt-Text","Alternativtext","alt","Bildbeschreibung","Screenreader"]},{"text":"Kontrast erhöhen: dunklere Schrift, mindestens 4,5:1 für normalen Text.","points":2,"keywords":["Kontrast","4,5:1","dunklere Schrift","lesbar"]},{"text":"Menü und alle Funktionen per Tastatur bedienbar machen, mit sichtbarem Fokus.","points":2,"keywords":["Tastatur","Tab-Taste","Fokus","ohne Maus"]},{"text":"Videos mit Untertiteln oder einem Transkript versehen.","points":2,"keywords":["Untertitel","Transkript","Textfassung"]},{"text":"Schrift vergrößerbar halten und verständliche Sprache bzw. klare Fehlermeldungen verwenden.","points":2,"keywords":["vergrößern","Schriftgröße","einfache Sprache","verständlich","Fehlermeldung"]}],"sample_solution":"Erstens erhalten alle Produktbilder aussagekräftige Alternativtexte, damit Screenreader sie vorlesen können. Zweitens wird der Kontrast erhöht, etwa dunkle Schrift auf hellem Grund mit mindestens 4,5:1. Drittens wird das Menü vollständig per Tastatur bedienbar gemacht und der Fokus sichtbar hervorgehoben. Zusätzlich sollten die Videos Untertitel oder ein Transkript bekommen."}'::jsonb,
  'current'
)
on conflict (id) do update set
