insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-mu-5',
  'multimedia_daten',
  'md-uebertragung',
  'open',
  'Für die Datensicherung der Kanzlei wurde eine Übertragungsdauer von rund 7 Stunden berechnet. In der ersten Nacht dauert die Sicherung jedoch fast 10 Stunden.',
  'Erläutere zwei mögliche Gründe, warum eine Übertragung in der Praxis länger dauert als berechnet.',
  'Je erläutertem Grund 2 Punkte, verlangt sind zwei. Die berechnete Dauer ist ein Bestwert: Sie setzt voraus, dass die volle Datenrate ununterbrochen und nur für diese Übertragung zur Verfügung steht.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Die Leitung wird mit anderen Anwendungen oder Nutzern geteilt - es steht nicht die volle Datenrate zur Verfügung.","points":2,"keywords":["geteilt","andere Nutzer","gleichzeitig","ausgelastet","Auslastung"]},{"text":"Der Anbieter liefert nicht dauerhaft die vertraglich genannte Maximalrate („bis zu“).","points":2,"keywords":["bis zu","Maximalrate","schwankt","Schwankung","tatsächliche Datenrate"]},{"text":"Protokoll-Overhead und Übertragungswiederholungen vergrößern die zu sendende Datenmenge.","points":2,"keywords":["Overhead","Header","Wiederholung","erneut senden","Paketverlust"]},{"text":"Die Gegenstelle oder ein Gerät auf dem Weg begrenzt die Rate (Server, WLAN, langsame Festplatte, Verschlüsselung).","points":2,"keywords":["Server","Gegenstelle","WLAN","Festplatte","Engpass","Flaschenhals"]}],"sample_solution":"Erstens teilt sich die Sicherung die Leitung mit anderen Anwendungen, sodass nicht die volle Upload-Rate zur Verfügung steht. Zweitens ist die vertragliche Datenrate ein Höchstwert („bis zu“), die tatsächliche Rate schwankt. Weitere Gründe: Protokoll-Overhead und wiederholt gesendete Pakete sowie Engpässe bei der Gegenstelle, im WLAN oder beim Lesen und Verschlüsseln der Daten."}'::jsonb,
  'current'
)
