insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-mu-6',
  'multimedia_daten',
  'md-uebertragung',
  'cloze',
  'In der neuen Lagerhalle der Elbtal Logistik AG senden 12 Kameras ihre Bilder über einen gemeinsamen Uplink mit 100 Mbit/s an den Aufzeichnungsserver. Jede Kamera erzeugt einen Datenstrom von 6 Mbit/s. Der Uplink soll höchstens zu 80 % ausgelastet werden.',
  'Prüfe, ob der Uplink ausreicht.',
  '12 Kameras × 6 Mbit/s = 72 Mbit/s. 80 % von 100 Mbit/s = 80 Mbit/s. 80 - 72 = 8 Mbit/s Reserve - der Uplink reicht aus, eine 14. Kamera (84 Mbit/s) würde die Grenze aber überschreiten.',
  1,
  '{}',
  null,
  '{"points":4,"cloze_text":"Datenrate aller Kameras in Mbit/s: {0}\nZulässige Auslastung des Uplinks in Mbit/s: {1}\nVerbleibende Reserve in Mbit/s: {2}\nDer Uplink ist damit {3}.","gaps":[{"answers":["72"],"numeric":true,"rationale":"12 × 6."},{"answers":["80"],"numeric":true,"rationale":"100 × 0,8."},{"answers":["8"],"numeric":true,"rationale":"80 - 72."},{"answers":["ausreichend"],"options":["ausreichend","zu knapp","überlastet"],"rationale":"72 Mbit/s liegen unter der Grenze von 80 Mbit/s."}]}'::jsonb,
