insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-mx-1',
  'multimedia_daten',
  'md-kompression',
  'cloze',
  'Eine Videodatei der Pixelhafen Medien GmbH ist unkomprimiert 80 MB groß. In drei Angeboten von Software-Herstellern wird die Kompression unterschiedlich beschrieben.',
  'Berechne jeweils die Größe der komprimierten Datei.',
  '„Um 30 %“: Es bleiben 70 % -> 80 × 0,7 = 56 MB. „Auf 30 %“: Es bleiben 30 % -> 80 × 0,3 = 24 MB. Faktor 4:1: 80 / 4 = 20 MB, das ist eine Einsparung von (1 - 20 / 80) × 100 = 75 %. Das kleine Wort „um“ oder „auf“ entscheidet über das Ergebnis.',
  2,
  '{}',
  null,
  '{"points":4,"cloze_text":"Angebot A, „verringert die Größe um 30 %“: {0} MB\nAngebot B, „verringert die Größe auf 30 %“: {1} MB\nAngebot C, „Kompressionsfaktor 4:1“: {2} MB\nEinsparung bei Angebot C in Prozent: {3}","gaps":[{"answers":["56"],"numeric":true,"rationale":"80 × 0,7."},{"answers":["24"],"numeric":true,"rationale":"80 × 0,3."},{"answers":["20"],"numeric":true,"rationale":"80 / 4."},{"answers":["75"],"numeric":true,"rationale":"(1 - 20 / 80) × 100."}]}'::jsonb,
