insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-mx-2',
  'multimedia_daten',
  'md-kompression',
  'open',
  'Die Pixelhafen Medien GmbH bereitet für einen Kunden Bildmaterial auf: Produktfotos für die Website und eingescannte Vertragsunterlagen für das Archiv. Der Kunde fragt, ob er alles einfach „stark als JPEG komprimieren“ kann.',
  'Erläutere den Unterschied zwischen verlustfreier und verlustbehafteter Kompression und gib an, welche Art für die beiden Einsatzzwecke jeweils geeignet ist.',
  'Je 1 Punkt für die beiden Erklärungen und für die beiden Zuordnungen. Verlustbehaftete Verfahren passen zu Fotos, Musik und Video; verlustfrei bleibt alles, was exakt erhalten werden muss: Texte, Programme, Dokumente, Grafiken mit harten Kanten.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Verlustfrei: Das Original lässt sich exakt wiederherstellen (z. B. PNG, ZIP).","points":1,"keywords":["exakt","vollständig wiederherstellen","ohne Verlust","Original","bitgenau"]},{"text":"Verlustbehaftet: Kaum wahrnehmbare Details werden entfernt, das Original ist nicht wiederherstellbar - dafür viel kleinere Dateien (z. B. JPEG).","points":1,"keywords":["Details entfernt","weggelassen","nicht wiederherstellbar","Qualitätsverlust","kleiner"]},{"text":"Produktfotos für die Website: verlustbehaftet (JPEG) - kleine Dateien, kurze Ladezeit.","points":1,"keywords":["Produktfotos","Fotos","Website","Ladezeit","JPEG"]},{"text":"Vertragsunterlagen im Archiv: verlustfrei - Schrift bleibt scharf und der Inhalt unverändert.","points":1,"keywords":["Vertragsunterlagen","Archiv","Dokumente","Schrift","unverändert","PNG"]}],"sample_solution":"Verlustfreie Kompression stellt das Original exakt wieder her, spart aber weniger Platz. Verlustbehaftete Kompression entfernt Details, die kaum wahrgenommen werden; die Datei wird viel kleiner, das Original lässt sich aber nicht zurückgewinnen. Für Produktfotos auf der Website eignet sich verlustbehaftetes JPEG (kurze Ladezeiten). Die Vertragsunterlagen im Archiv sollten verlustfrei gespeichert werden, damit Schrift und Inhalt unverändert bleiben."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  data = excluded.data,
  catalog_status = excluded.catalog_status,
  is_active = true;

insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-mx-3',
  'multimedia_daten',
  'md-kompression',
  'marking',
  'Ein Kunde der Pixelhafen Medien GmbH kann eine gelieferte MP4-Datei nicht abspielen. Im englischen Hilfetext des Abspielprogramms steht der folgende Abschnitt.',
  'Markiere alle Aussagen, die sich dem Text entnehmen lassen.',
  'Der Text trennt Container (MP4: hält die Spuren zusammen) und Codec (H.264: komprimiert). Abspielbar ist eine Datei nur, wenn das Programm den Codec unterstützt - die Endung allein sagt wenig. „Lossy“ heißt verlustbehaftet.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"choices":[{"text":"Der Container hält Video- und Tonspuren zusammen.","is_correct":true,"rationale":"„holds the video and audio tracks together“."},{"text":"Der Codec komprimiert die Bilder.","is_correct":true,"rationale":"„The codec ... compresses the pictures“."},{"text":"MP4 ist ein Codec.","is_correct":false,"rationale":"MP4 wird als Beispiel für einen Container genannt."},{"text":"Ob eine Datei abgespielt werden kann, hängt vom verwendeten Codec ab.","is_correct":true,"rationale":"„only if it supports the codec that was used“."},{"text":"Die meisten Videocodecs arbeiten verlustfrei.","is_correct":false,"rationale":"„lossy“ bedeutet verlustbehaftet."},{"text":"Entfernt werden Details, die Zuschauer kaum bemerken.","is_correct":true,"rationale":"„details that viewers hardly notice are removed“."},{"text":"Eine MP4-Datei enthält immer genau eine Spur.","is_correct":false,"rationale":"Der Text spricht von mehreren Spuren („tracks“)."}],"code":"A video file usually consists\nof a container and one or more\ncodecs. The container, for\nexample MP4, only holds the\nvideo and audio tracks\ntogether. The codec, such as\nH.264, compresses the pictures.\nA player can open a file only\nif it supports the codec that\nwas used. Most video codecs are\nlossy: details that viewers\nhardly notice are removed.","points":4}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
