insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ig-1',
  'ki_grundlagen',
  'ki-grundlagen',
  'open',
  'Die Geschäftsführung der Elbtal Logistik AG hat einen englischen Fachartikel über künstliche Intelligenz erhalten und bittet dich um eine kurze Auswertung.',
  'Beschreibe auf Deutsch anhand des Textes, wodurch sich maschinelles Lernen von klassischer Programmierung unterscheidet. Nenne außerdem zwei der im Text genannten Anwendungen.',
  '2 Punkte für den Unterschied (lernen aus Beispieldaten statt fester Regeln), je 1 Punkt für zwei der drei genannten Anwendungen. Gewertet wird nur, was im Text steht - eigene Beispiele zählen hier nicht.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"code":"Artificial intelligence (AI) is\nthe ability of computer systems\nto perform tasks that normally\nrequire human intelligence.\nMachine learning is a part of\nAI: the system is not programmed\nwith fixed rules, but learns\npatterns from large amounts of\nexample data. Typical uses are\nrecognising speech, sorting\ne-mails and detecting faulty\nproducts in photos.","points":4,"criteria":[{"text":"Unterschied: Das System erhält keine fest programmierten Regeln, sondern lernt Muster aus vielen Beispieldaten.","points":2,"keywords":["lernt","Muster","Beispieldaten","keine festen Regeln","Daten"]},{"text":"Anwendung: Sprache erkennen","points":1,"keywords":["Sprache","Spracherkennung","gesprochene"]},{"text":"Anwendung: E-Mails sortieren","points":1,"keywords":["E-Mail","Mails","sortieren"]},{"text":"Anwendung: fehlerhafte Produkte auf Fotos erkennen","points":1,"keywords":["fehlerhafte Produkte","Fotos","Bilder","defekte","Qualitätskontrolle"]}],"sample_solution":"Beim maschinellen Lernen wird das System nicht mit festen Regeln programmiert, sondern lernt Muster aus großen Mengen von Beispieldaten. Genannte Anwendungen: Spracherkennung, das Sortieren von E-Mails und das Erkennen fehlerhafter Produkte auf Fotos."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  data = excluded.data,
  catalog_status = excluded.catalog_status,
