  null,
  '{"points":3,"pairs":[{"left":"Trainingsdaten","right":"Beispiele, aus denen das Modell lernt"},{"left":"Label","right":"richtige Antwort zu einem Beispiel"},{"left":"Testdaten","right":"ungesehene Daten zur Bewertung"},{"left":"Token","right":"Textbaustein eines Sprachmodells"},{"left":"Overfitting","right":"Trainingsdaten auswendig gelernt"},{"left":"Halluzination","right":"plausibel klingende, falsche Ausgabe"}]}'::jsonb,
