insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ig-4',
  'ki_grundlagen',
  'ki-grundlagen',
  'open',
  'Die Elbtal Logistik AG lässt ein Modell trainieren, das auf Fotos beschädigte Pakete erkennt. Alle Trainingsfotos wurden in Halle 1 bei Tageslicht aufgenommen. Im Training erkennt das Modell 99 % der Fälle richtig, im Betrieb in der neuen Halle mit Kunstlicht nur noch 68 %.',
  'Erläutere die wahrscheinliche Ursache und beschreibe eine Maßnahme, mit der sich das Ergebnis verbessern lässt.',
  '2 Punkte für die Ursache (einseitige Trainingsdaten, Overfitting), 2 Punkte für eine beschriebene Maßnahme. Ein großer Abstand zwischen Trainings- und Praxisergebnis ist das typische Zeichen dafür, dass das Modell nicht verallgemeinert.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Ursache: Die Trainingsdaten sind einseitig (nur Halle 1, nur Tageslicht) - das Modell ist darauf überangepasst (Overfitting) und verallgemeinert schlecht.","points":2,"keywords":["Overfitting","überangepasst","einseitig","nicht repräsentativ","auswendig","verallgemeinert"]},{"text":"Maßnahme: mit mehr und vielfältigeren Fotos trainieren (andere Hallen, Kunstlicht, verschiedene Blickwinkel).","points":2,"keywords":["vielfältiger","mehr Daten","weitere Fotos","andere Halle","Kunstlicht","neu trainieren"]},{"text":"Maßnahme: das Modell vor dem Einsatz mit getrennten Testdaten aus der realen Umgebung prüfen.","points":2,"keywords":["Testdaten","testen","prüfen","reale Umgebung","Validierung"]}],"sample_solution":"Die Trainingsfotos stammen nur aus Halle 1 bei Tageslicht. Das Modell hat sich an diese Bedingungen überangepasst (Overfitting) und kommt mit dem Kunstlicht der neuen Halle nicht zurecht. Maßnahme: das Modell mit zusätzlichen, vielfältigeren Fotos aus allen Hallen und Lichtverhältnissen neu trainieren und vor dem Einsatz mit getrennten Testdaten aus der realen Umgebung bewerten."}'::jsonb,
  'current'
)
on conflict (id) do update set
