insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ie-1',
  'ki_grundlagen',
  'ki-einsatz',
  'table',
  'Die Kessler & Brandt IT-Systemhaus GmbH möchte KI im Support einsetzen. Der Ablauf einer Störungsmeldung besteht aus fünf Schritten. Für den ersten Schritt ist die KI-Unterstützung als Muster eingetragen.',
  'Wähle zu jedem weiteren Prozessschritt die passende Möglichkeit der KI-Unterstützung.',
  'KI eignet sich für Sprache, Text und Muster: Transkribieren, Klassifizieren, ähnliche Fälle finden, Entwürfe schreiben, Zusammenfassen. Was an Kunden geht, wird vorher von einem Menschen geprüft - die Verantwortung bleibt beim Techniker.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Prozessschritt"},{"text":"KI-Unterstützung"}],[{"text":"1. Kunde schildert das Problem am Telefon"},{"text":"Gespräch automatisch in Text umwandeln"}],[{"text":"2. Ticket wird einem Fachteam zugewiesen"},{"gap":{"answers":["Ticket nach seinem Inhalt klassifizieren"],"options":["Ticket nach seinem Inhalt klassifizieren","Gesprochenes in Text umwandeln","Antwortmail formulieren"]}}],[{"text":"3. Techniker sucht nach der Ursache"},{"gap":{"answers":["ähnliche gelöste Tickets vorschlagen"],"options":["ähnliche gelöste Tickets vorschlagen","Ticket nach Inhalt klassifizieren","Verlauf zusammenfassen"]}}],[{"text":"4. Techniker antwortet dem Kunden"},{"gap":{"answers":["Antwortentwurf erstellen, den der Techniker prüft"],"options":["Antwortentwurf erstellen, den der Techniker prüft","Antwort ohne Prüfung versenden","ähnliche Tickets vorschlagen"]}}],[{"text":"5. Übergabe des offenen Tickets an die nächste Schicht"},{"gap":{"answers":["langen Ticketverlauf zusammenfassen"],"options":["langen Ticketverlauf zusammenfassen","Gesprochenes in Text umwandeln","Ticket ungelesen schließen"]}}]]}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  data = excluded.data,
  catalog_status = excluded.catalog_status,
  is_active = true;

insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ie-2',
  'ki_grundlagen',
  'ki-einsatz',
  'open',
  'Einige Techniker der Kessler & Brandt IT-Systemhaus GmbH stehen der KI-gestützten Ticketbearbeitung skeptisch gegenüber. Die Teamleitung möchte in der nächsten Besprechung für die Einführung werben.',
  'Beschreibe zwei Argumente, die für den Einsatz von KI in der Ticketbearbeitung sprechen.',
  'Je beschriebenem Argument 2 Punkte (Aussage plus kurze Ausführung), verlangt sind zwei. Typische Argumente: Entlastung, Zeitersparnis, Mustererkennung, gleichbleibende Qualität, Skalierbarkeit ohne mehr Personal.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Entlastung von Routinearbeit: Sortieren, Zusammenfassen und Entwürfe übernimmt die KI - es bleibt mehr Zeit für schwierige Fälle.","points":2,"keywords":["Routine","Entlastung","entlastet","mehr Zeit","Zeitersparnis"]},{"text":"Schnellere Bearbeitung: Kunden erhalten früher eine Antwort, Tickets landen sofort beim richtigen Team.","points":2,"keywords":["schneller","Wartezeit","Bearbeitungszeit","sofort","Reaktionszeit"]},{"text":"Wissen nutzen: Das System erkennt Muster und findet ähnliche gelöste Fälle, die ein Einzelner nicht kennt.","points":2,"keywords":["Muster","ähnliche Fälle","Wissen","Wissensdatenbank","Erfahrung"]},{"text":"Gleichbleibende Qualität und weniger Flüchtigkeitsfehler, auch bei hohem Ticketaufkommen ohne zusätzliches Personal.","points":2,"keywords":["Qualität","weniger Fehler","skalierbar","ohne mehr Personal","Kosten"]}],"sample_solution":"Erstens entlastet die KI von Routinearbeit wie dem Vorsortieren und Zusammenfassen von Tickets, sodass den Technikern mehr Zeit für anspruchsvolle Störungen bleibt. Zweitens werden Tickets schneller bearbeitet: Sie gelangen sofort zum richtigen Team, und Kunden erhalten früher eine Antwort. Weitere Argumente: Die KI findet ähnliche gelöste Fälle und hält die Qualität auch bei vielen Tickets konstant."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
