insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ir-1',
  'ki_grundlagen',
  'ki-grenzen',
  'marking',
  'Ein Kunde fragt nach dem Router NetGate R20. Ein Kollege lässt die Antwort von einem KI-Chatbot formulieren. Du vergleichst die Aussagen mit dem Datenblatt des Herstellers. Eine Zeitschrift namens „NetzProfi“ lässt sich nirgends finden.',
  'Markiere alle Aussagen des Chatbots, die auf eine Halluzination hindeuten.',
  'Halluzinationen sind flüssig formulierte, aber falsche oder erfundene Angaben - oft Zahlen, Normen und Quellen. Erkennen lassen sie sich nur durch den Abgleich mit verlässlichen Unterlagen wie dem Datenblatt. Vor dem Versand an Kunden muss ein Mensch prüfen.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"„Der Router hat vier Gigabit-LAN-Ports.“","is_correct":false,"rationale":"Stimmt mit dem Datenblatt überein."},{"text":"„Er funkt nach Wi-Fi 7.“","is_correct":true,"rationale":"Laut Datenblatt Wi-Fi 6 - die Angabe ist erfunden."},{"text":"„Als VPN-Verfahren steht WireGuard bereit.“","is_correct":false,"rationale":"Stimmt mit dem Datenblatt überein."},{"text":"„Die Garantie beträgt fünf Jahre.“","is_correct":true,"rationale":"Laut Datenblatt 2 Jahre - eine falsche Zusage mit rechtlichen Folgen."},{"text":"„Laut NetzProfi 03/2025 ist er Testsieger.“","is_correct":true,"rationale":"Die Quelle existiert nicht - erfundene Belege sind typisch für Halluzinationen."},{"text":"„Das WLAN arbeitet nach Wi-Fi 6.“","is_correct":false,"rationale":"Stimmt mit dem Datenblatt überein."}],"table":[["Merkmal","Datenblatt"],["LAN-Ports","4 × 1 Gbit/s"],["WLAN","Wi-Fi 6"],["VPN","WireGuard"],["Garantie","2 Jahre"]],"points":3}'::jsonb,
  'current'
)
