insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ir-2',
  'ki_grundlagen',
  'ki-grenzen',
  'open',
  'Die Grünwerk Gartenbedarf GmbH will im Webshop einen KI-Chatbot einsetzen, der Kundenfragen zu Bestellungen, Lieferzeiten und Reklamationen selbstständig beantwortet.',
  'Beschreibe zwei Risiken, die mit dem Einsatz des Chatbots verbunden sind.',
  'Je beschriebenem Risiko 2 Punkte (Risiko plus Folge), verlangt sind zwei. Nach der EU-KI-Verordnung muss außerdem erkennbar sein, dass die Kunden mit einer KI kommunizieren.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Falsche Auskünfte (Halluzinationen), z. B. erfundene Lieferzeiten oder Zusagen - Folge: verärgerte Kunden, Imageschaden, rechtliche Ansprüche.","points":2,"keywords":["falsche Auskunft","Halluzination","erfunden","falsche Zusage","Falschinformation"]},{"text":"Datenschutz: Der Chatbot verarbeitet personenbezogene Daten, die beim externen Anbieter landen können (Rechtsgrundlage, AVV nötig).","points":2,"keywords":["Datenschutz","personenbezogen","DSGVO","Kundendaten","AVV"]},{"text":"Manipulation: Durch geschickte Eingaben (Prompt Injection) lässt sich der Chatbot zu unerwünschten Aussagen oder Rabatten bringen.","points":2,"keywords":["Prompt Injection","Manipulation","manipulieren","austricksen","Missbrauch"]},{"text":"Akzeptanz: Kunden fühlen sich abgewimmelt, wenn kein Mensch erreichbar ist oder nicht erkennbar ist, dass eine KI antwortet (Transparenzpflicht).","points":2,"keywords":["Akzeptanz","kein Mensch","unzufrieden","Transparenz","Kennzeichnung"]}],"sample_solution":"Risiko 1: Der Chatbot kann falsche Auskünfte geben, etwa erfundene Lieferzeiten oder Zusagen bei Reklamationen. Das verärgert Kunden und kann rechtliche Folgen haben. Risiko 2: Der Chatbot verarbeitet personenbezogene Kundendaten; ohne Rechtsgrundlage und Vertrag mit dem Anbieter drohen Datenschutzverstöße. Weitere Risiken sind die Manipulation durch geschickte Eingaben und fehlende Akzeptanz, wenn kein Mensch erreichbar ist."}'::jsonb,
  'current'
)
on conflict (id) do update set
