insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i4-ir-4',
  'ki_grundlagen',
  'ki-grenzen',
  'open',
  'Die Pixelhafen Medien GmbH erarbeitet eine Richtlinie für den Umgang mit KI-Werkzeugen. Als Grundlage dient ein Abschnitt aus einem englischen Leitfaden.',
  'Nenne auf Deutsch drei Risiken, die der Text beschreibt.',
  'Je Nennung 1 Punkt, höchstens 3 - der Text enthält vier Risiken. Stichworte auf Deutsch genügen. „Prejudice“ bedeutet Vorurteil, „confidential“ vertraulich.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"code":"Generative AI tools are useful,\nbut they bring risks. They can\nproduce answers that sound\ncorrect but are wrong. Their\ntraining data may contain\nprejudice, so some groups of\npeople are treated unfairly.\nConfidential data that\nemployees type into a public\ntool may leave the company.\nFinally, staff may trust the\nresults too much and stop\nchecking them.","points":3,"criteria":[{"text":"Antworten, die richtig klingen, aber falsch sind","points":1,"keywords":["falsch","falsche Antworten","Halluzination","fehlerhaft"]},{"text":"Vorurteile in den Trainingsdaten - Gruppen werden unfair behandelt","points":1,"keywords":["Vorurteil","unfair","Bias","benachteiligt","Diskriminierung"]},{"text":"Vertrauliche Daten können das Unternehmen verlassen","points":1,"keywords":["vertrauliche Daten","Datenabfluss","verlassen","Geheimnisse","öffentliches Tool"]},{"text":"Beschäftigte vertrauen den Ergebnissen zu sehr und prüfen nicht mehr","points":1,"keywords":["zu sehr vertrauen","blind","nicht mehr prüfen","ungeprüft","Vertrauen"]}],"sample_solution":"Der Text nennt vier Risiken: Antworten können richtig klingen, aber falsch sein. Die Trainingsdaten können Vorurteile enthalten, sodass Gruppen unfair behandelt werden. Vertrauliche Daten, die in ein öffentliches Werkzeug eingegeben werden, können das Unternehmen verlassen. Beschäftigte können den Ergebnissen zu sehr vertrauen und sie nicht mehr prüfen."}'::jsonb,
  'current'
)
