insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i5-qg-1',
  'qualitaetsmanagement',
  'qm-grundlagen',
  'pairs',
  'Ein Softwarehaus überarbeitet sein Qualitätshandbuch. Im Glossar sollen sechs Grundbegriffe der Qualitätssicherung erklärt werden.',
  'Ordne jedem Begriff die passende Erklärung zu. (6 P.)',
  'Konstruktiv beugt vor (Richtlinien, Schulung), analytisch prüft nach (Review, Test). Statisch heißt ohne, dynamisch mit Ausführung. Verifikation: richtig gebaut? Validierung: das Richtige gebaut?',
  2,
  '{}',
  null,
  '{"points":6,"pairs":[{"left":"konstruktive QS","right":"Fehler von vornherein vermeiden"},{"left":"analytische QS","right":"Fehler in fertigen Ergebnissen finden"},{"left":"statische Prüfung","right":"Prüfen, ohne das Programm auszuführen"},{"left":"dynamische Prüfung","right":"Prüfen durch Ausführen des Programms"},{"left":"Verifikation","right":"Prüfung gegen die Spezifikation"},{"left":"Validierung","right":"Prüfung gegen den Bedarf des Kunden"}]}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
