  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-zz-3',
  'schutzziele_bedrohungen',
  'sz-schutzziele',
  'table',
  'Ein Hosting-Anbieter bietet drei Tarife mit unterschiedlicher zugesicherter Verfügbarkeit an. Gerechnet wird mit 8.760 Stunden je Jahr und einem Monat mit 30 Tagen (43.200 Minuten).',
  'Berechne die höchstens zulässige Ausfallzeit je Tarif und ergänze die Tabelle.',
  'Zulässiger Ausfall = (100 % - Verfügbarkeit) × Betriebszeit. 99,5 %: 0,005 × 8.760 h = 43,8 h und 0,005 × 43.200 min = 216 min. 99,9 %: 0,001 × 8.760 h = 8,76 h und 0,001 × 43.200 min = 43,2 min.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Verfügbarkeit"},{"text":"Ausfall je Jahr (h)"},{"text":"Ausfall je Monat (min)"}],[{"text":"99 %"},{"text":"87,6"},{"text":"432"}],[{"text":"99,5 %"},{"gap":{"answers":["43.8"],"numeric":true,"tolerance":0.05,"rationale":"0,005 × 8.760 h = 43,8 h"}},{"gap":{"answers":["216"],"numeric":true,"rationale":"0,005 × 43.200 min = 216 min"}}],[{"text":"99,9 %"},{"gap":{"answers":["8.76"],"numeric":true,"tolerance":0.01,"rationale":"0,001 × 8.760 h = 8,76 h"}},{"gap":{"answers":["43.2"],"numeric":true,"tolerance":0.05,"rationale":"0,001 × 43.200 min = 43,2 min"}}]]}'::jsonb,
