insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-zb-2',
  'schutzziele_bedrohungen',
  'sz-schutzbedarf',
  'cloze',
  'Auf einem Server laufen drei Anwendungen: die Zeiterfassung (Schutzbedarf normal), die Lohnabrechnung (hoch) und das Intranet (normal).',
  'Ergänze die Aussagen zur Vererbung des Schutzbedarfs.',
  'Maximumprinzip: Der höchste Schutzbedarf der Anwendungen vererbt sich auf das System - hier „hoch“. Kumulationseffekt: Viele kleinere Schäden summieren sich zu einem größeren. Verteilungseffekt: Redundanz senkt den Bedarf des einzelnen Systems.',
  2,
  '{}',
  null,
  '{"points":4,"cloze_text":"Der Server erhält nach dem {0} den Schutzbedarf {1}, weil die Anwendung mit dem höchsten Bedarf maßgeblich ist. Laufen sehr viele Anwendungen mit normalem Bedarf auf einem Server, kann sein Bedarf durch den {2} steigen, weil ein Ausfall alle zugleich trifft. Ist eine Anwendung auf mehrere redundante Server verteilt, kann der Bedarf des einzelnen Servers durch den {3} sinken.","gaps":[{"answers":["Maximumprinzip"],"options":["Maximumprinzip","Minimalprinzip","Verteilungseffekt"]},{"answers":["hoch"],"options":["hoch","normal","sehr hoch"],"rationale":"Die Lohnabrechnung bestimmt den Bedarf."},{"answers":["Kumulationseffekt"],"options":["Kumulationseffekt","Verteilungseffekt","Lawineneffekt"]},{"answers":["Verteilungseffekt"],"options":["Verteilungseffekt","Kumulationseffekt","Maximumprinzip"]}]}'::jsonb,
