insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-yf-1',
  'sicherheitsmassnahmen',
  'sm-firewall',
  'table',
  'Die Pixelhafen Medien GmbH betreibt einen Webserver in der DMZ. Vorgaben: Aus dem Internet ist nur HTTPS zum Webserver erlaubt. Die Administratoren warten den Webserver vom LAN aus per SSH. Alles andere wird verworfen.',
  'Ergänze das Regelwerk der Firewall.',
  'HTTPS nutzt TCP 443, SSH nutzt TCP 22. Verbindungen aus dem Internet ins LAN werden verworfen. Als letzte Regel steht immer „alles verwerfen“ (Default Deny) - erlaubt ist nur, was ausdrücklich freigegeben wurde.',
  2,
  '{}',
  null,
  '{"points":5,"grid":[[{"text":"Quelle"},{"text":"Ziel"},{"text":"Port"},{"text":"Aktion"}],[{"text":"Internet"},{"text":"Webserver (DMZ)"},{"gap":{"answers":["TCP 443"],"options":["TCP 443","TCP 23","TCP 25","UDP 53"],"rationale":"HTTPS"}},{"text":"erlauben"}],[{"text":"Admin-PC (LAN)"},{"text":"Webserver (DMZ)"},{"gap":{"answers":["TCP 22"],"options":["TCP 22","TCP 21","TCP 23","TCP 3389"],"rationale":"SSH"}},{"gap":{"answers":["erlauben"],"options":["erlauben","verwerfen","umleiten"]}}],[{"text":"Internet"},{"gap":{"answers":["LAN"],"options":["LAN","Webserver (DMZ)","Internet"],"rationale":"Kein Zugriff von außen ins interne Netz."}},{"text":"alle"},{"text":"verwerfen"}],[{"text":"alle"},{"text":"alle"},{"text":"alle"},{"gap":{"answers":["verwerfen"],"options":["verwerfen","erlauben","protokollieren"],"rationale":"Default Deny als letzte Regel"}}]]}'::jsonb,
  'current'
)
