insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-yf-2',
  'sicherheitsmassnahmen',
  'sm-firewall',
  'marking',
  'Sicherheitsrichtlinie: Aus dem Internet ist nur HTTPS zum Webserver in der DMZ erlaubt. Aus dem Internet und aus der DMZ dürfen keine Verbindungen ins LAN aufgebaut werden. Bei der Prüfung der Firewall findest du folgendes Regelwerk.',
  'Markiere alle Regeln, die gegen die Richtlinie verstoßen.',
  'Regel 2 öffnet das LAN nach außen, Regel 4 erlaubt neben HTTPS auch RDP zum Webserver, Regel 5 hebt die Trennung zwischen DMZ und LAN auf. Wird der Webserver übernommen, stünde dem Angreifer sonst das ganze LAN offen.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"1 ALLOW Internet -> DMZ-Web  tcp/443","is_correct":false,"rationale":"HTTPS zum Webserver ist ausdrücklich erlaubt."},{"text":"2 ALLOW Internet -> LAN-File tcp/445","is_correct":true,"rationale":"Dateifreigaben aus dem Internet ins LAN - klarer Verstoß."},{"text":"3 ALLOW LAN      -> Internet tcp/80,443","is_correct":false,"rationale":"Surfen aus dem LAN verbietet die Richtlinie nicht."},{"text":"4 ALLOW Internet -> DMZ-Web  tcp/3389","is_correct":true,"rationale":"Fernwartung (RDP) aus dem Internet ist nicht vorgesehen - nur HTTPS."},{"text":"5 ALLOW DMZ-Web  -> LAN      any","is_correct":true,"rationale":"Die DMZ darf keine Verbindungen ins LAN aufbauen."},{"text":"6 DENY  any      -> any      any","is_correct":false,"rationale":"Default Deny am Ende ist richtig."}],"points":3,"mono":true}'::jsonb,
  'current'
)
