insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-yb-1',
  'sicherheitsmassnahmen',
  'sm-backup',
  'table',
  'Am Sonntag läuft eine Vollsicherung mit 200 GB. Von Montag bis Donnerstag werden täglich 10 GB jeweils anderer Dateien geändert und abends gesichert. Verglichen werden zwei Verfahren. Am Freitagmorgen fällt der Server aus.',
  'Ergänze die Größe der täglichen Sicherung in GB und die Anzahl der Sicherungen, die für die Wiederherstellung nötig sind.',
  'Differenziell: immer alle Änderungen seit der letzten Vollsicherung - 10, 20, 30, 40 GB. Zurückgespielt werden nur die Vollsicherung und die letzte differenzielle (2). Inkrementell: nur die Änderungen seit der letzten Sicherung - jeweils 10 GB. Zurückgespielt werden die Vollsicherung und alle vier Inkremente (5).',
  2,
  '{}',
  null,
  '{"points":7,"grid":[[{"text":"Tag"},{"text":"differenziell"},{"text":"inkrementell"}],[{"text":"Montag"},{"text":"10"},{"text":"10"}],[{"text":"Dienstag"},{"gap":{"answers":["20"],"numeric":true,"rationale":"alle Änderungen seit Sonntag: 10 + 10"}},{"gap":{"answers":["10"],"numeric":true,"rationale":"nur die Änderungen seit Montag"}}],[{"text":"Mittwoch"},{"gap":{"answers":["30"],"numeric":true}},{"text":"10"}],[{"text":"Donnerstag"},{"gap":{"answers":["40"],"numeric":true,"rationale":"4 × 10 GB seit der Vollsicherung"}},{"gap":{"answers":["10"],"numeric":true}}],[{"text":"Sicherungen für die Wiederherstellung"},{"gap":{"answers":["2"],"numeric":true,"rationale":"Vollsicherung + Donnerstag"}},{"gap":{"answers":["5"],"numeric":true,"rationale":"Vollsicherung + Mo, Di, Mi, Do"}}]]}'::jsonb,
  'current'
)
