insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-yb-2',
  'sicherheitsmassnahmen',
  'sm-backup',
  'open',
  'Die Pixelhafen Medien GmbH sichert ihre Projektdaten bisher jede Nacht vollständig. Das dauert inzwischen zu lange. Zur Wahl stehen eine differenzielle und eine inkrementelle Sicherung an den Werktagen.',
  'Beschreibe zwei Unterschiede zwischen differenzieller und inkrementeller Sicherung. (4 P.)',
  'Je Unterschied 2 Punkte, höchstens 4 Punkte. Wichtig ist der Vergleich beider Verfahren, nicht nur die Beschreibung eines. Andere fachlich richtige Antworten zählen ebenfalls.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Umfang: differenziell sichert alle Änderungen seit der letzten Vollsicherung, inkrementell nur die Änderungen seit der letzten Sicherung","points":2,"keywords":["seit der letzten Vollsicherung","seit der letzten Sicherung","seit dem letzten Backup","Änderungen seit"]},{"text":"Speicher und Dauer: inkrementelle Sicherungen bleiben klein und schnell, differenzielle wachsen von Tag zu Tag","points":2,"keywords":["Speicherplatz","Speicherbedarf","kleiner","schneller","wächst"]},{"text":"Wiederherstellung: differenziell braucht Vollsicherung und letzte differenzielle, inkrementell die Vollsicherung und alle Inkremente - dauert länger, eine defekte Sicherung unterbricht die Kette","points":2,"keywords":["Wiederherstellung","Restore","alle Inkremente","Kette","zurückspielen"]}],"sample_solution":"Die differenzielle Sicherung enthält alle Änderungen seit der letzten Vollsicherung und wird deshalb täglich größer. Die inkrementelle enthält nur die Änderungen seit der letzten Sicherung und bleibt klein und schnell. Dafür braucht die Wiederherstellung bei inkrementeller Sicherung die Vollsicherung und alle Inkremente in der richtigen Reihenfolge, bei differenzieller nur die Vollsicherung und die letzte differenzielle."}'::jsonb,
  'current'
)
