insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-yw-3',
  'sicherheitsmassnahmen',
  'sm-wlan',
  'cloze',
  'Für ein Angebot an die Steuerkanzlei Albers & Partner beschreibst du die Absicherung des neuen WLAN.',
  'Ergänze den Text.',
  'WPA2/WPA3-Personal: ein gemeinsamer Schlüssel (PSK) für alle. WPA3 handelt ihn per SAE aus. Im Enterprise-Modus meldet sich jede Person einzeln nach 802.1X an, ein RADIUS-Server prüft die Zugangsdaten - beim Ausscheiden muss kein gemeinsamer Schlüssel getauscht werden.',
  2,
  '{}',
  null,
  '{"points":5,"cloze_text":"Im Modus „Personal“ melden sich alle Geräte mit demselben {0} an. WPA3 ersetzt dessen Aushandlung durch das Verfahren {1} und schützt so vor Wörterbuchangriffen auf mitgeschnittene Anmeldungen. Für die Kanzlei empfehlen wir den Modus {2}: Jede Person meldet sich nach dem Standard {3} mit eigenen Zugangsdaten an, die ein {4}-Server prüft. Scheidet jemand aus, wird nur dieses eine Konto gesperrt.","gaps":[{"answers":["Pre-Shared Key (PSK)"],"options":["Pre-Shared Key (PSK)","Zertifikat","Sitzungsschlüssel"]},{"answers":["SAE"],"options":["SAE","TKIP","WPS","WEP"]},{"answers":["Enterprise"],"options":["Enterprise","Personal","Open"]},{"answers":["802.1X"],"options":["802.1X","802.3af","802.11n","802.1Q"]},{"answers":["RADIUS"],"options":["RADIUS","DHCP","DNS","NTP"]}]}'::jsonb,
