insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-ca-5',
  'kryptographie_auth',
  'kr-asymmetrisch',
  'open',
  'Ein Lieferant erhält von der Elbtal Logistik AG einen digital signierten, aber nicht verschlüsselten Frachtauftrag.',
  'Beschreibe anhand der Skizze, wie die digitale Signatur erstellt und wie sie geprüft wird. (4 P.)',
  '2 Punkte für das Erstellen (privater Schlüssel des Absenders), 2 Punkte für das Prüfen (öffentlicher Schlüssel des Absenders). Auch die Kurzfassung „mit dem privaten Schlüssel signieren, mit dem öffentlichen prüfen“ reicht - entscheidend ist, wessen Schlüssel es sind.',
  2,
  '{}',
  null,
  '{"diagram":{"type":"sequenz","teilnehmer":["Elbtal","Lieferant"],"nachrichten":[{"von":0,"an":1,"text":"Zertifikat (öff. Schlüssel)"},{"von":0,"an":1,"text":"Auftrag + Signatur"}]},"criteria":[{"text":"Erstellen: Aus dem Auftrag wird ein Hashwert gebildet und mit dem privaten Schlüssel des Absenders verschlüsselt; Auftrag und Signatur werden gesendet","points":2,"keywords":["privaten Schlüssel","privater Schlüssel","private Schlüssel","private key"]},{"text":"Prüfen: Der Empfänger entschlüsselt die Signatur mit dem öffentlichen Schlüssel des Absenders, berechnet den Hashwert selbst und vergleicht beide Werte","points":2,"keywords":["öffentlichen Schlüssel","öffentlicher Schlüssel","öffentliche Schlüssel","public key"]}],"sample_solution":"Elbtal bildet den Hashwert des Auftrags und verschlüsselt ihn mit dem eigenen privaten Schlüssel - das Ergebnis ist die Signatur. Auftrag und Signatur gehen an den Lieferanten. Dieser entschlüsselt die Signatur mit dem öffentlichen Schlüssel von Elbtal und erhält den ursprünglichen Hashwert. Er berechnet den Hashwert des erhaltenen Auftrags selbst und vergleicht: Stimmen beide überein, ist der Auftrag unverändert und stammt von Elbtal."}'::jsonb,
  'current'
)
