insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-ch-1',
  'kryptographie_auth',
  'kr-hybrid',
  'cloze',
  'Die Pixelhafen Medien GmbH schickt einem Kunden große Entwurfsdateien hybrid verschlüsselt.',
  'Ergänze die Beschreibung des hybriden Verfahrens.',
  'Hybrid heißt: Die Nutzdaten werden schnell symmetrisch mit einem zufälligen Sitzungsschlüssel verschlüsselt. Nur dieser kurze Schlüssel wird asymmetrisch mit dem öffentlichen Schlüssel des Empfängers geschützt. So verbindet das Verfahren Geschwindigkeit mit einfachem Schlüsselaustausch.',
  2,
  '{}',
  null,
  '{"diagram":{"type":"sequenz","teilnehmer":["Agentur","Kunde"],"nachrichten":[{"von":1,"an":0,"text":"öffentlicher Schlüssel"},{"von":0,"an":1,"text":"Sitzungsschlüssel (verschl.)"},{"von":0,"an":1,"text":"Datei (verschlüsselt)"}]},"points":5,"cloze_text":"Die Agentur erzeugt einen zufälligen {0} und verschlüsselt damit die Datei {1}, zum Beispiel mit AES. Den Sitzungsschlüssel selbst verschlüsselt sie {2} mit dem Schlüssel {3}. Der Kunde entschlüsselt zuerst den Sitzungsschlüssel mit dem Schlüssel {4} und damit anschließend die Datei.","gaps":[{"answers":["Sitzungsschlüssel"],"options":["Sitzungsschlüssel","Hashwert","privaten Schlüssel"]},{"answers":["symmetrisch"],"options":["symmetrisch","asymmetrisch","gar nicht"]},{"answers":["asymmetrisch"],"options":["asymmetrisch","symmetrisch","mit einem Hashverfahren"]},{"answers":["öffentlich (Empfänger)"],"options":["öffentlich (Empfänger)","privat (Sender)","öffentlich (Sender)","privat (Empfänger)"],"rationale":"Der Kunde ist der Empfänger."},{"answers":["privat (Empfänger)"],"options":["privat (Empfänger)","privat (Sender)","öffentlich (Sender)","öffentlich (Empfänger)"]}]}'::jsonb,
  'current'
)
