insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-ch-2',
  'kryptographie_auth',
  'kr-hybrid',
  'open',
  'Beim Aufruf des Webshops der Grünwerk Gartenbedarf GmbH über HTTPS kommen ein asymmetrisches und ein symmetrisches Verfahren zum Einsatz.',
  'Erläutere, warum hybride Verfahren beide Verschlüsselungsarten kombinieren. (4 P.)',
  'Je 2 Punkte für die Rolle des symmetrischen Verfahrens (Tempo) und des asymmetrischen Verfahrens (Schlüsselaustausch). Andere fachlich richtige Antworten zählen ebenfalls.',
  2,
  '{}',
  null,
  '{"criteria":[{"text":"Symmetrische Verfahren sind schnell und eignen sich für große Datenmengen, haben aber das Problem des Schlüsselaustauschs","points":2,"keywords":["schnell","große Datenmengen","Schlüsselaustausch","performant","Rechenaufwand"]},{"text":"Asymmetrische Verfahren lösen den Schlüsselaustausch, sind aber langsam - sie schützen deshalb nur den kurzen Sitzungsschlüssel","points":2,"keywords":["langsam","Sitzungsschlüssel","Session Key","rechenaufwendig","kein geheimer Austausch"]}],"sample_solution":"Symmetrische Verfahren wie AES sind schnell und für große Datenmengen geeignet, beide Seiten brauchen aber denselben geheimen Schlüssel. Asymmetrische Verfahren brauchen keinen geheimen Schlüsselaustausch, sind aber rechenaufwendig und langsam. Hybride Verfahren nutzen deshalb das asymmetrische Verfahren nur, um einen Sitzungsschlüssel sicher zu vereinbaren, und verschlüsseln die eigentlichen Daten symmetrisch."}'::jsonb,
  'current'
)
