insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-cx-5',
  'kryptographie_auth',
  'kr-hash',
  'open',
  'Bei der Prüfung einer älteren Webanwendung der Pixelhafen Medien GmbH stellst du fest, dass die Passwörter der Kunden im Klartext in der Datenbank stehen.',
  'Beschreibe zwei Maßnahmen, mit denen Passwörter sicher gespeichert werden. (4 P.)',
  'Je Maßnahme 2 Punkte, höchstens 4 Punkte. Wird die Datenbank gestohlen, liegen so keine Passwörter im Klartext vor. Andere fachlich richtige Antworten zählen ebenfalls.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Nur den Hashwert des Passworts speichern; bei der Anmeldung wird die Eingabe gehasht und verglichen","points":2,"keywords":["Hashwert","hashen","gehasht","Hash","Einwegfunktion"]},{"text":"Je Passwort einen zufälligen Salt verwenden: gleiche Passwörter ergeben verschiedene Hashwerte, Rainbow-Tables werden nutzlos","points":2,"keywords":["Salt","Rainbow","Zufallswert","gesalzen"]},{"text":"Ein absichtlich langsames Passwort-Hashverfahren wie bcrypt oder Argon2 einsetzen, um Brute Force zu bremsen","points":2,"keywords":["bcrypt","Argon2","langsam","PBKDF2","Brute Force"]}],"sample_solution":"Statt des Passworts wird nur sein Hashwert gespeichert; bei der Anmeldung wird die Eingabe gehasht und mit dem gespeicherten Wert verglichen. Zusätzlich erhält jedes Passwort einen eigenen zufälligen Salt, damit gleiche Passwörter unterschiedliche Hashwerte ergeben und vorberechnete Tabellen nicht helfen. Geeignet sind absichtlich langsame Verfahren wie bcrypt oder Argon2."}'::jsonb,
  'current'
)
