insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-cz-1',
  'kryptographie_auth',
  'kr-auth',
  'table',
  'Für die Anmeldung an den Kassen der neuen Filiale vergleicht die Grünwerk Gartenbedarf GmbH drei Arten von Authentifizierungsfaktoren.',
  'Ergänze zu jedem Faktor ein Beispiel und ein typisches Risiko.',
  'Wissen (Passwort, PIN): kann erraten, ausgespäht oder weitergegeben werden. Besitz (Chipkarte, Token): kann verloren gehen oder gestohlen werden. Biometrie (Fingerabdruck): kann nicht vergessen werden, lässt sich aber nicht ändern, wenn das Merkmal einmal kopiert wurde.',
  2,
  '{}',
  null,
  '{"points":6,"grid":[[{"text":"Faktor"},{"text":"Beispiel"},{"text":"Risiko"}],[{"text":"Wissen"},{"gap":{"answers":["Passwort oder PIN"],"options":["Passwort oder PIN","Chipkarte","Fingerabdruck"]}},{"gap":{"answers":["kann erraten oder ausgespäht werden"],"options":["kann erraten oder ausgespäht werden","kann verloren gehen oder gestohlen werden","lässt sich nach Missbrauch nicht ändern"]}}],[{"text":"Besitz"},{"gap":{"answers":["Chipkarte"],"options":["Chipkarte","Passwort oder PIN","Fingerabdruck"]}},{"gap":{"answers":["kann verloren gehen oder gestohlen werden"],"options":["kann verloren gehen oder gestohlen werden","kann erraten oder ausgespäht werden","lässt sich nach Missbrauch nicht ändern"]}}],[{"text":"Biometrie"},{"gap":{"answers":["Fingerabdruck"],"options":["Fingerabdruck","Passwort oder PIN","Chipkarte"]}},{"gap":{"answers":["lässt sich nach Missbrauch nicht ändern"],"options":["lässt sich nach Missbrauch nicht ändern","kann erraten oder ausgespäht werden","kann verloren gehen oder gestohlen werden"]}}]]}'::jsonb,
  'current'
)
