insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-cz-3',
  'kryptographie_auth',
  'kr-auth',
  'open',
  'Die 20 Beschäftigten der Grünwerk Gartenbedarf GmbH, die mobil arbeiten, melden sich am VPN bisher nur mit Benutzername und Passwort an. Die IT-Abteilung will eine Zwei-Faktor-Authentifizierung einführen.',
  'Erläutere, warum eine Zwei-Faktor-Authentifizierung besser schützt als ein Passwort allein. (4 P.)',
  '2 Punkte für das Prinzip (zwei verschiedene Faktorkategorien), 2 Punkte für die Folge (ein gestohlenes Passwort genügt nicht mehr). Andere fachlich richtige Antworten zählen ebenfalls.',
  2,
  '{}',
  null,
  '{"criteria":[{"text":"Es werden zwei Nachweise aus verschiedenen Kategorien verlangt (Wissen, Besitz, Biometrie)","points":2,"keywords":["verschiedene Kategorien","zwei Faktoren","Wissen und Besitz","unterschiedliche Faktoren"]},{"text":"Ein ausgespähtes oder erratenes Passwort reicht allein nicht - der Angreifer bräuchte zusätzlich den zweiten Faktor, z. B. das Smartphone","points":2,"keywords":["reicht nicht","zusätzlich","Phishing","gestohlenes Passwort","Smartphone","Token"]}],"sample_solution":"Bei der Zwei-Faktor-Authentifizierung müssen zwei Nachweise aus verschiedenen Kategorien erbracht werden, zum Beispiel das Passwort (Wissen) und ein Einmalcode aus einer App auf dem Smartphone (Besitz). Wird das Passwort durch Phishing oder ein Datenleck bekannt, kann sich der Angreifer trotzdem nicht anmelden, weil ihm der zweite Faktor fehlt."}'::jsonb,
  'current'
)
