insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-cz-4',
  'kryptographie_auth',
  'kr-auth',
  'multiple',
  'Die Pixelhafen Medien GmbH arbeitet für einen internationalen Kunden und muss dessen Passwortrichtlinie einhalten.',
  'Welche Vorgaben macht die Richtlinie? Wähle alle zutreffenden aus.',
  'Der Text verlangt: mindestens 14 Zeichen, keine Wiederverwendung, Wechsel nur bei Verdacht, Passwortmanager des Unternehmens und von außen zusätzlich einen Einmalcode. Ein regelmäßiger Wechsel, Sonderzeichen und Kontosperren stehen nicht im Text.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"choices":[{"text":"Mindestens 14 Zeichen Länge","is_correct":true,"rationale":"„at least 14 characters long“"},{"text":"Ein Passwort darf für keinen anderen Dienst wiederverwendet werden","is_correct":true,"rationale":"„must not be reused for any other service“"},{"text":"Passwörter werden im bereitgestellten Passwortmanager gespeichert","is_correct":true,"rationale":"„store their passwords in the password manager provided by the company“"},{"text":"Beim Zugriff von außerhalb ist zusätzlich ein Einmalcode aus der App nötig","is_correct":true,"rationale":"„additionally requires a one-time code from the authenticator app“"},{"text":"Passwörter müssen alle 90 Tage gewechselt werden","is_correct":false,"rationale":"Im Gegenteil: Gewechselt wird nur bei Verdacht auf Kompromittierung."},{"text":"Jedes Passwort muss ein Sonderzeichen enthalten","is_correct":false,"rationale":"Zur Zusammensetzung sagt der Text nichts."},{"text":"Nach drei Fehlversuchen wird das Konto gesperrt","is_correct":false,"rationale":"Eine Kontosperre wird im Text nicht erwähnt."}],"code":"PASSWORD POLICY (excerpt)\n\nPasswords must be at least 14 characters long. A password\nmust not be reused for any other service. Passwords are\nonly changed if there is a suspicion that they have been\ncompromised. All employees have to store their passwords\nin the password manager provided by the company. Access\nfrom outside the office additionally requires a one-time\ncode from the authenticator app.","points":4}'::jsonb,
  'current'
)
