values (
  'i6-cz-5',
  'kryptographie_auth',
  'kr-auth',
  'cloze',
  'Die Anmeldung am VPN-Portal wird um einen Einmalcode aus einer Authenticator-App (TOTP) ergänzt.',
  'Ergänze die Beschreibung des Verfahrens.',
  'TOTP = Time-based One-Time Password: App und Server berechnen aus dem gemeinsamen Geheimnis und der Uhrzeit denselben Code, der meist 30 Sekunden gilt. Passwort = Wissen, Smartphone mit App = Besitz - zusammen eine echte Zwei-Faktor-Authentifizierung.',
  2,
  '{}',
  null,
  '{"diagram":{"type":"sequenz","teilnehmer":["Nutzer","Portal","App"],"nachrichten":[{"von":0,"an":1,"text":"Benutzername + Passwort"},{"von":1,"an":0,"text":"Code anfordern","antwort":true},{"von":2,"an":0,"text":"Einmalcode"},{"von":0,"an":1,"text":"Einmalcode"},{"von":1,"an":0,"text":"Zugang","antwort":true}]},"points":5,"cloze_text":"Bei der Einrichtung tauschen Portal und App per QR-Code ein gemeinsames {0} aus. Daraus und aus der aktuellen {1} berechnen beide denselben Code, der nur etwa {2} Sekunden gilt. Das Passwort gehört zur Faktorkategorie {3}, das Smartphone mit der App zur Kategorie {4}.","gaps":[{"answers":["Geheimnis"],"options":["Geheimnis","Zertifikat","Passwort des Nutzers"]},{"answers":["Uhrzeit"],"options":["Uhrzeit","IP-Adresse","Passwortlänge"]},{"answers":["30"],"numeric":true},{"answers":["Wissen"],"options":["Wissen","Besitz","Biometrie"]},{"answers":["Besitz"],"options":["Besitz","Wissen","Biometrie"]}]}'::jsonb,
