insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-xg-1',
  'datenschutz',
  'ds-grundlagen',
  'marking',
  'Die Personalabteilung der Elbtal Logistik AG führt zu jeder beschäftigten Person eine digitale Personalakte. Für besondere Kategorien personenbezogener Daten (Art. 9 DSGVO) sollen strengere Zugriffsregeln gelten.',
  'Markiere alle Einträge, die zu den besonderen Kategorien personenbezogener Daten gehören.',
  'Besondere Kategorien nach Art. 9 DSGVO sind unter anderem Gesundheitsdaten, religiöse Überzeugung, Gewerkschaftszugehörigkeit, politische Meinung, ethnische Herkunft, genetische Daten und biometrische Daten zur eindeutigen Identifizierung. Anschrift, Bankverbindung, Geburtsdatum und Steuerklasse sind „gewöhnliche“ personenbezogene Daten.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Privatanschrift","is_correct":false,"rationale":"Personenbezogen, aber keine besondere Kategorie."},{"text":"Religionszugehörigkeit (für die Kirchensteuer)","is_correct":true,"rationale":"Religiöse Überzeugung nennt Art. 9 ausdrücklich."},{"text":"Bankverbindung (IBAN)","is_correct":false,"rationale":"Schützenswert, aber nicht in Art. 9 genannt."},{"text":"Ärztliches Attest mit Diagnose","is_correct":true,"rationale":"Gesundheitsdaten gehören zu den besonderen Kategorien."},{"text":"Mitgliedschaft in einer Gewerkschaft","is_correct":true,"rationale":"Gewerkschaftszugehörigkeit nennt Art. 9 ausdrücklich."},{"text":"Geburtsdatum","is_correct":false,"rationale":"Ein gewöhnliches personenbezogenes Datum."},{"text":"Fingerabdruck für die Zutrittskontrolle","is_correct":true,"rationale":"Biometrische Daten zur eindeutigen Identifizierung fallen unter Art. 9."},{"text":"Steuerklasse","is_correct":false,"rationale":"Personenbezogen, aber keine besondere Kategorie."}],"points":4}'::jsonb,
  'current'
)
