insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-xg-2',
  'datenschutz',
  'ds-grundlagen',
  'open',
  'Die Kessler & Brandt IT-Systemhaus GmbH wartet die Server der Steuerkanzlei Albers & Partner. Dabei können Techniker Mandantendaten einsehen. Die Kanzlei verlangt deshalb besonders strenge Schutzmaßnahmen.',
  'Nenne zwei rechtliche Grundlagen, aus denen sich die erhöhten Anforderungen an den Schutz der Mandantendaten ergeben. (2 P.)',
  'Je Nennung 1 Punkt, höchstens 2 Punkte. Bei Kanzleien, Arztpraxen und Apotheken tritt neben das Datenschutzrecht immer das Berufsgeheimnis nach § 203 StGB.',
  2,
  '{}',
  null,
  '{"points":2,"criteria":[{"text":"Datenschutz-Grundverordnung (DSGVO)","points":1,"keywords":["DSGVO","Datenschutz-Grundverordnung","Datenschutzgrundverordnung","GDPR"]},{"text":"Bundesdatenschutzgesetz (BDSG)","points":1,"keywords":["BDSG","Bundesdatenschutzgesetz","Datenschutzgesetz"]},{"text":"Berufsgeheimnis der Steuerberater: Verschwiegenheitspflicht, strafbewehrt durch § 203 StGB","points":1,"keywords":["Berufsgeheimnis","Verschwiegenheit","203","StGB","Schweigepflicht","Steuerberatungsgesetz"]}],"sample_solution":"Die DSGVO (ergänzt durch das BDSG) schützt die personenbezogenen Daten der Mandanten. Daneben unterliegen Steuerberater dem Berufsgeheimnis: Die Verletzung von Privatgeheimnissen ist nach § 203 StGB strafbar. Auch Dienstleister, die an der Berufsausübung mitwirken, müssen zur Verschwiegenheit verpflichtet werden."}'::jsonb,
  'current'
)
