insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-xg-3',
  'datenschutz',
  'ds-grundlagen',
  'matching',
  'Die Steuerkanzlei Albers & Partner verarbeitet Daten ihrer Mandanten und Beschäftigten. Das Systemhaus betreut die Server per Fernwartung, ein Rechenzentrum speichert die verschlüsselten Sicherungen.',
  'Ordne jedem Beteiligten seine Rolle nach der DSGVO zu.',
  'Verantwortlicher ist, wer über Zwecke und Mittel der Verarbeitung entscheidet - hier die Kanzlei. Auftragsverarbeiter verarbeiten Daten nach Weisung des Verantwortlichen (Rechenzentrum, Systemhaus) und brauchen einen Vertrag nach Art. 28 DSGVO. Betroffene Personen sind die Menschen, deren Daten verarbeitet werden.',
  2,
  '{}',
  null,
  '{"buckets":["Verantwortlicher","Auftragsverarbeiter","Betroffene Person"],"match_items":[{"text":"Rechenzentrum, das die Sicherungen im Auftrag speichert","bucket":1,"rationale":"Verarbeitet nur nach Weisung der Kanzlei."},{"text":"Mandantin, deren Steuererklärung erstellt wird","bucket":2,"rationale":"Um ihre Daten geht es."},{"text":"Steuerkanzlei Albers & Partner","bucket":0,"rationale":"Sie entscheidet über Zwecke und Mittel der Verarbeitung."},{"text":"Systemhaus, das die Server per Fernwartung betreut","bucket":1,"rationale":"Hat im Auftrag der Kanzlei Zugriff auf die Daten."},{"text":"Angestellter der Kanzlei, dessen Gehalt abgerechnet wird","bucket":2,"rationale":"Auch Beschäftigte sind betroffene Personen."}],"points":5}'::jsonb,
  'current'
)
