insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-xs-2',
  'datenschutz',
  'ds-grundsaetze',
  'open',
  'Die Elbtal Logistik AG will die Laderampen und das Hoftor der neuen Lagerhalle mit Kameras überwachen, um Diebstähle aufzuklären.',
  'Nenne drei Pflichten, die das Unternehmen bei der Videoüberwachung aus Sicht des Datenschutzes einhalten muss. (3 P.)',
  'Je Nennung 1 Punkt, höchstens 3 Punkte. Rechtsgrundlage ist in der Regel das berechtigte Interesse (Art. 6 Abs. 1 lit. f DSGVO) - es muss gegen die Interessen der Gefilmten abgewogen werden.',
  2,
  '{}',
  null,
  '{"points":3,"criteria":[{"text":"Auf die Überwachung deutlich hinweisen (Schild mit Verantwortlichem und Zweck)","points":1,"keywords":["Hinweisschild","Schild","hinweisen","Hinweis","kennzeichnen"]},{"text":"Zweck vorab festlegen und Interessen abwägen: nur so viel überwachen wie erforderlich (berechtigtes Interesse)","points":1,"keywords":["Zweck","Interessenabwägung","berechtigtes Interesse","erforderlich","abwägen"]},{"text":"Keine Erfassung von öffentlichem Raum, Nachbargrundstücken, Pausen-, Umkleide- und Sanitärräumen","points":1,"keywords":["öffentlicher Raum","öffentlichen Raum","Pausenraum","Umkleide","Sanitär","Nachbargrundstück"]},{"text":"Aufnahmen nur kurz speichern und danach löschen (Richtwert der Aufsichtsbehörden: 72 Stunden)","points":1,"keywords":["löschen","Speicherdauer","Speicherfrist","72","Löschfrist"]},{"text":"Aufnahmen vor unbefugtem Zugriff schützen (Zugriffsrechte, Verschlüsselung)","points":1,"keywords":["Zugriffsschutz","unbefugt","Zugriffsrechte","geschützt","verschlüsselt"]},{"text":"Betriebsrat beteiligen und die Verarbeitung dokumentieren","points":1,"keywords":["Betriebsrat","Mitbestimmung","dokumentieren","Verzeichnis"]}],"sample_solution":"Das Unternehmen muss durch gut sichtbare Schilder auf die Überwachung hinweisen, den Zweck vorab festlegen und seine Interessen gegen die der Betroffenen abwägen. Die Kameras dürfen nur das Nötige erfassen - keinen öffentlichen Raum und keine Pausen- oder Umkleideräume. Aufnahmen werden vor unbefugtem Zugriff geschützt und nach kurzer Zeit gelöscht. Der Betriebsrat ist zu beteiligen."}'::jsonb,
  'current'
)
