insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i6-xt-4',
  'datenschutz',
  'ds-tom',
  'open',
  'Die Elbtal Logistik AG arbeitet mit einem internationalen Kunden zusammen. Dessen Richtlinie für Sicherheitsvorfälle gilt auch für Dienstleister.',
  'Nenne vier Schritte, die die Richtlinie bei einem möglichen Datenschutzvorfall verlangt. Antworte auf Deutsch. (4 P.)',
  'Je Nennung 1 Punkt, höchstens 4 Punkte. Der Text enthält fünf Schritte; gewertet wird nur, was im Text steht. Das Gerät bleibt eingeschaltet, damit Spuren im Arbeitsspeicher erhalten bleiben.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"code":"INCIDENT RESPONSE POLICY (excerpt)\n\nAny employee who notices a possible data breach must\nreport it to the IT service desk immediately. The affected\ndevice has to be disconnected from the network, but it\nmust not be switched off. The service desk informs the\ndata protection officer within one hour. All steps taken\nare recorded in the incident log.","points":4,"criteria":[{"text":"Vorfall sofort dem IT-Servicedesk melden","points":1,"keywords":["Servicedesk","Service Desk","sofort melden","melden"]},{"text":"Betroffenes Gerät vom Netzwerk trennen","points":1,"keywords":["vom Netz trennen","Netzwerk trennen","trennen","Netzwerkkabel"]},{"text":"Gerät nicht ausschalten","points":1,"keywords":["nicht ausschalten","nicht abschalten","eingeschaltet lassen","nicht herunterfahren"]},{"text":"Servicedesk informiert den Datenschutzbeauftragten innerhalb einer Stunde","points":1,"keywords":["Datenschutzbeauftragte","eine Stunde","einer Stunde","DSB"]},{"text":"Alle Schritte im Vorfallsprotokoll festhalten","points":1,"keywords":["Protokoll","dokumentieren","festhalten","aufzeichnen"]}],"sample_solution":"Die Richtlinie verlangt: den möglichen Vorfall sofort dem IT-Servicedesk melden, das betroffene Gerät vom Netzwerk trennen, es aber nicht ausschalten, den Datenschutzbeauftragten innerhalb einer Stunde durch den Servicedesk informieren und alle Schritte im Vorfallsprotokoll festhalten."}'::jsonb,
  'current'
)
