insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-vz-1',
  'vertraege',
  'vt-zustandekommen',
  'table',
  'Ein Systemhaus beschafft für eine Steuerkanzlei 18 Notebooks. In der Akte liegt der Schriftverkehr mit dem Lieferanten.',
  'Ordne jedem Vorgang seine rechtliche Bedeutung zu und gib an, mit welchem Vorgang der Kaufvertrag zustande kommt.',
  'Anfrage = unverbindlich. Angebot an einen bestimmten Kunden = Antrag, hier befristet bis 19.03. Die Bestellung vom 21.03. kommt zu spät und ist deshalb ein neuer Antrag (§ 150 Abs. 1 BGB). Mit der Auftragsbestätigung vom 22.03. nimmt der Lieferant an - erst jetzt besteht der Vertrag.',
  2,
  '{}',
  null,
  '{"points":5,"grid":[[{"text":"Datum"},{"text":"Vorgang"},{"text":"Rechtliche Bedeutung"}],[{"text":"03.03."},{"text":"Das Systemhaus fragt per E-Mail nach Preisen für 18 Notebooks."},{"gap":{"answers":["Anfrage (unverbindlich)"],"options":["Anfrage (unverbindlich)","Antrag","Annahme","neuer Antrag"],"rationale":"Eine Anfrage bindet niemanden."}}],[{"text":"05.03."},{"text":"Der Lieferant schickt ein Angebot, gültig bis 19.03."},{"gap":{"answers":["Antrag"],"options":["Antrag","Anfrage (unverbindlich)","Annahme","Aufforderung zum Antrag"],"rationale":"Ein Angebot an einen bestimmten Kunden ist ein verbindlicher Antrag."}}],[{"text":"21.03."},{"text":"Das Systemhaus bestellt zu den Bedingungen des Angebots."},{"gap":{"answers":["neuer Antrag"],"options":["neuer Antrag","Annahme","Anfrage (unverbindlich)","Aufforderung zum Antrag"],"rationale":"Die Frist ist seit dem 19.03. abgelaufen - eine verspätete Annahme gilt als neuer Antrag (§ 150 Abs. 1 BGB)."}}],[{"text":"22.03."},{"text":"Der Lieferant schickt eine Auftragsbestätigung."},{"gap":{"answers":["Annahme"],"options":["Annahme","Antrag","neuer Antrag","Anfrage (unverbindlich)"],"rationale":"Der Lieferant nimmt den neuen Antrag des Systemhauses an."}}],[{"text":"Ergebnis"},{"text":"Der Kaufvertrag kommt zustande am"},{"gap":{"answers":["22.03."],"options":["22.03.","05.03.","21.03.","19.03."],"rationale":"Erst an diesem Tag liegen Antrag und Annahme übereinstimmend vor."}}]]}'::jsonb,
