insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-vy-2',
  'vertraege',
  'vt-arten',
  'open',
  'Ein Handelsunternehmen lässt von einem Softwarehaus ein Kundenportal entwickeln. Das Softwarehaus schlägt vor, „nach Aufwand“ auf Stundenbasis abzurechnen.',
  'Erläutere zwei Unterschiede zwischen Werkvertrag und Dienstvertrag.',
  'Je Unterschied 2 Punkte, höchstens 4 Punkte. Für das Handelsunternehmen ist der Werkvertrag günstiger, weil das Softwarehaus für das funktionierende Ergebnis einstehen muss.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Geschuldet: beim Werkvertrag ein Erfolg (fertiges Werk), beim Dienstvertrag nur die Tätigkeit","points":2,"keywords":["Erfolg","Ergebnis","Tätigkeit","Bemühen","fertig"]},{"text":"Abnahme und Vergütung: Werkvertrag mit Abnahme, erst dann wird die Vergütung fällig; Dienstvertrag ohne Abnahme, Vergütung nach Zeit","points":2,"keywords":["Abnahme","fällig","nach Stunden","nach Zeit","Aufwand"]},{"text":"Mängel: Werkvertrag mit Mängelrechten (Nacherfüllung, Minderung, Rücktritt); Dienstvertrag kennt keine Gewährleistung","points":2,"keywords":["Mängelrechte","Gewährleistung","Nacherfüllung","Nachbesserung","Mangel"]},{"text":"Risiko: Beim Werkvertrag trägt der Unternehmer das Risiko des Misserfolgs, beim Dienstvertrag der Auftraggeber","points":2,"keywords":["Risiko","Misserfolg","trägt","Mehraufwand"]}],"sample_solution":"Beim Werkvertrag schuldet der Unternehmer einen Erfolg, etwa das lauffähige Portal; beim Dienstvertrag nur das Tätigwerden. Deshalb gibt es beim Werkvertrag eine Abnahme, mit der die Vergütung fällig wird, und Mängelrechte, wenn das Werk Fehler hat. Beim Dienstvertrag wird nach geleisteter Zeit bezahlt, auch wenn das Ergebnis ausbleibt - das Risiko trägt der Auftraggeber."}'::jsonb,
  'current'
)
