insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-gv-3',
  'leistungsstoerungen',
  'ls-verzug',
  'cloze',
  'Ein Systemhaus hat einem Handwerksbetrieb 7.300 € in Rechnung gestellt. Der Betrieb ist seit 60 Tagen im Zahlungsverzug. Nimm für diese Aufgabe einen Basiszinssatz von 2 % an und rechne mit 365 Tagen im Jahr.',
  'Berechne die Forderungen aus dem Zahlungsverzug.',
  'Unter Unternehmen: Basiszinssatz + 9 Prozentpunkte = 2 % + 9 = 11 %. Jahreszinsen: 7.300 € × 0,11 = 803 €. Für 60 Tage: 803 € × 60 / 365 = 132 €. Dazu die Pauschale von 40 €: 132 € + 40 € = 172 €. Wäre ein Verbraucher beteiligt, wären es nur 5 Prozentpunkte und keine Pauschale.',
  2,
  '{}',
  null,
  '{"points":6,"cloze_text":"Aufschlag unter Unternehmen: {0} Prozentpunkte\nVerzugszinssatz: {1} %\nZinsen für ein ganzes Jahr: {2} €\nZinsen für 60 Tage: {3} €\nVerzugspauschale: {4} €\nZinsen und Pauschale zusammen: {5} €","gaps":[{"answers":["9"],"numeric":true,"rationale":"§ 288 Abs. 2 BGB: kein Verbraucher beteiligt"},{"answers":["11"],"numeric":true,"rationale":"2 % + 9 Prozentpunkte"},{"answers":["803"],"numeric":true,"rationale":"7.300 € × 0,11"},{"answers":["132"],"numeric":true,"rationale":"803 € × 60 / 365"},{"answers":["40"],"numeric":true,"rationale":"§ 288 Abs. 5 BGB"},{"answers":["172"],"numeric":true,"rationale":"132 € + 40 €"}],"mono":true}'::jsonb,
  'current'
)
