insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-gv-4',
  'leistungsstoerungen',
  'ls-verzug',
  'marking',
  'Ein Handwerksbetrieb (Unternehmer) hat eine Rechnung über 4.800 € nicht bezahlt. Im Vertrag ist als Zahlungstermin der 16. Mai vereinbart, heute ist der 30. Mai. Ein Auszubildender hat eine Mahnung entworfen.',
  'Markiere alle Sätze der Mahnung, die fachlich falsch oder ungeeignet sind.',
  'Bei einem vertraglich vereinbarten Kalendertermin tritt Verzug ohne Mahnung ein - hier ab dem 17. Mai. Unter Unternehmern betragen die Verzugszinsen 9 Prozentpunkte über dem Basiszinssatz, dazu kommt die Pauschale von 40 €. Eine Mahnung fordert bestimmt und mit Datum zur Zahlung auf.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"Zu unserer Rechnung Nr. 2291 über 4.800,00 € konnten wir noch keinen Zahlungseingang feststellen.","is_correct":false,"rationale":"Rechnung und Betrag sind eindeutig benannt."},{"text":"Bitte überweisen Sie den Betrag irgendwann in den nächsten Wochen.","is_correct":true,"rationale":"Eine Mahnung muss eindeutig zur Zahlung auffordern und sollte ein konkretes Datum nennen."},{"text":"Da Sie Verbraucher sind, berechnen wir Verzugszinsen von 9 Prozentpunkten über dem Basiszinssatz.","is_correct":true,"rationale":"Der Kunde ist Unternehmer. Die 9 Prozentpunkte gelten gerade, wenn kein Verbraucher beteiligt ist; bei Verbrauchern wären es 5."},{"text":"Zusätzlich berechnen wir die Verzugspauschale von 40,00 €.","is_correct":false,"rationale":"Unter Unternehmern zulässig (§ 288 Abs. 5 BGB)."},{"text":"Verzug tritt erst nach unserer dritten Mahnung ein.","is_correct":true,"rationale":"Falsch: Der Zahlungstermin ist nach dem Kalender bestimmt, der Kunde ist seit dem 17. Mai in Verzug."},{"text":"Sollten Sie inzwischen gezahlt haben, betrachten Sie dieses Schreiben bitte als gegenstandslos.","is_correct":false,"rationale":"Üblicher und sinnvoller Schlusssatz."}],"points":3}'::jsonb,
  'current'
)
