insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-gv-5',
  'leistungsstoerungen',
  'ls-verzug',
  'ordering',
  'Ein Kunde zahlt eine fällige Rechnung nicht. Das Systemhaus will die Forderung durchsetzen.',
  'Bringe die Schritte in die übliche Reihenfolge.',
  'Erst außergerichtlich erinnern und mahnen, dann das gerichtliche Mahnverfahren: Mahnbescheid, bei ausbleibendem Widerspruch Vollstreckungsbescheid, zuletzt Zwangsvollstreckung. Rechtlich nötig ist höchstens eine Mahnung - mehrere Mahnstufen sind nur kaufmännische Übung.',
  2,
  '{}',
  null,
  '{"ordered_items":["Freundliche Zahlungserinnerung schicken","Mahnung mit konkreter Zahlungsfrist schicken","Mahnbescheid beim Mahngericht beantragen","Kunde legt keinen Widerspruch ein","Vollstreckungsbescheid beantragen","Zwangsvollstreckung, z. B. durch den Gerichtsvollzieher"],"points":3}'::jsonb,
  'current'
)
