insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-ga-1',
  'leistungsstoerungen',
  'ls-abnahme',
  'table',
  'Bei der Abnahme eines Kundenportals werden vier Mängel festgestellt. Der Vertrag kennt drei Mängelklassen: betriebsverhindernd (Abnahme wird verweigert), betriebsbehindernd (Abnahme wird in der Regel verweigert) und leicht (Abnahme unter Vorbehalt).',
  'Ordne jedem Mangel die Mängelklasse zu.',
  'Betriebsverhindernd: Nutzung unmöglich. Betriebsbehindernd: Nutzung stark eingeschränkt. Leicht: Nutzung kaum beeinträchtigt. Wegen des Anmeldefehlers darf der Besteller die Abnahme verweigern; wegen unwesentlicher Mängel allein dürfte er es nicht (§ 640 Abs. 1 Satz 2 BGB).',
  1,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Festgestellter Mangel"},{"text":"Mängelklasse"}],[{"text":"Kein Kunde kann sich anmelden."},{"gap":{"answers":["betriebsverhindernd"],"options":["betriebsverhindernd","betriebsbehindernd","leicht"],"rationale":"Das Portal ist nicht nutzbar."}}],[{"text":"Im Impressum steht ein Tippfehler."},{"gap":{"answers":["leicht"],"options":["leicht","betriebsverhindernd","betriebsbehindernd"],"rationale":"Die Nutzung ist nicht beeinträchtigt."}}],[{"text":"Der Rechnungsdruck funktioniert nur über einen umständlichen Umweg."},{"gap":{"answers":["betriebsbehindernd"],"options":["betriebsbehindernd","betriebsverhindernd","leicht"],"rationale":"Nutzbar, aber stark eingeschränkt."}}],[{"text":"Ein Symbol in der Fußzeile ist leicht verschoben."},{"gap":{"answers":["leicht"],"options":["leicht","betriebsverhindernd","betriebsbehindernd"],"rationale":"Rein optisch, unwesentlich."}}]]}'::jsonb,
  'current'
)
