insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-ga-2',
  'leistungsstoerungen',
  'ls-abnahme',
  'open',
  'Bei der Abnahme einer Lagerverwaltungssoftware fällt dem Kunden auf, dass der Etikettendruck fehlerhaft ist. Der Projektleiter des Auftragnehmers sagt: „Das beheben wir nächste Woche, unterschreiben Sie ruhig schon einmal.“',
  'Beschreibe zwei Gründe, warum der Kunde den Mangel mit einer Frist in das Abnahmeprotokoll aufnehmen lassen sollte.',
  'Je Grund 2 Punkte, höchstens 4 Punkte. Die mündliche Zusage des Projektleiters hilft später wenig - was nicht im Protokoll steht, lässt sich kaum beweisen.',
  2,
  '{}',
  null,
  '{"points":4,"criteria":[{"text":"Wer ein Werk trotz bekanntem Mangel ohne Vorbehalt abnimmt, verliert dafür Nacherfüllung, Selbstvornahme, Rücktritt und Minderung (§ 640 Abs. 3 BGB)","points":2,"keywords":["Vorbehalt","Rechte verlieren","verliert","Mängelrechte","640"]},{"text":"Das Protokoll ist der Beweis: Nach der Abnahme muss der Besteller beweisen, dass ein Mangel vorliegt","points":2,"keywords":["Beweis","Beweislast","Nachweis","belegen"]},{"text":"Mit der Frist ist festgelegt, bis wann nachgebessert wird; nach ihrem Ablauf stehen weitere Rechte offen","points":2,"keywords":["Frist","Termin","bis wann","verbindlich"]},{"text":"Mit dem Vorbehalt kann der Kunde einen angemessenen Teil der Vergütung zurückhalten","points":2,"keywords":["zurückhalten","einbehalten","Vergütung","Druckmittel"]}],"sample_solution":"Nimmt der Kunde ohne Vorbehalt ab, obwohl er den Mangel kennt, verliert er dafür seine Rechte auf Nacherfüllung, Selbstvornahme, Rücktritt und Minderung (§ 640 Abs. 3 BGB). Außerdem kehrt sich mit der Abnahme die Beweislast um: Das Protokoll belegt, dass der Mangel schon bei der Abnahme vorlag. Die Frist legt verbindlich fest, bis wann nachgebessert wird, und der Kunde kann bis dahin einen angemessenen Teil der Vergütung zurückhalten."}'::jsonb,
  'current'
)
