insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'i7-cl-2',
  'change_management',
  'cm-lewin',
  'table',
  'In der Phase des Veränderns muss entschieden werden, wie ein neues System in Betrieb geht.',
  'Ordne jeder Einführungsstrategie das Vorgehen und den typischen Nachteil zu.',
  'Sofortumstellung: schnell und billig, aber riskant. Parallelbetrieb: sicher, aber doppelter Aufwand. Stufenweise: überschaubare Schritte, aber lange Dauer und Schnittstellen zwischen alt und neu. Pilot: Fehler treffen nur einen Bereich, die übrigen profitieren erst später.',
  2,
  '{}',
  null,
  '{"points":4,"grid":[[{"text":"Strategie"},{"text":"Vorgehen"},{"text":"Typischer Nachteil"}],[{"text":"Sofortumstellung (Big Bang)"},{"gap":{"answers":["Stichtag: alt aus, neu an"],"options":["Stichtag: alt aus, neu an","alt und neu laufen nebeneinander","erst ein Bereich, dann alle","Modul für Modul umstellen"]}},{"gap":{"answers":["Fehler treffen sofort den ganzen Betrieb"],"options":["Fehler treffen sofort den ganzen Betrieb","doppelte Arbeit und Kosten","dauert lange, Schnittstellen nötig","Nutzen kommt für die anderen später"]}}],[{"text":"Parallelbetrieb"},{"gap":{"answers":["alt und neu laufen nebeneinander"],"options":["alt und neu laufen nebeneinander","Stichtag: alt aus, neu an","erst ein Bereich, dann alle","Modul für Modul umstellen"]}},{"gap":{"answers":["doppelte Arbeit und Kosten"],"options":["doppelte Arbeit und Kosten","Fehler treffen sofort den ganzen Betrieb","dauert lange, Schnittstellen nötig","Nutzen kommt für die anderen später"]}}],[{"text":"Stufenweise Einführung"},{"gap":{"answers":["Modul für Modul umstellen"],"options":["Modul für Modul umstellen","Stichtag: alt aus, neu an","alt und neu laufen nebeneinander","erst ein Bereich, dann alle"]}},{"gap":{"answers":["dauert lange, Schnittstellen nötig"],"options":["dauert lange, Schnittstellen nötig","Fehler treffen sofort den ganzen Betrieb","doppelte Arbeit und Kosten","Nutzen kommt für die anderen später"]}}],[{"text":"Pilotbetrieb"},{"gap":{"answers":["erst ein Bereich, dann alle"],"options":["erst ein Bereich, dann alle","Stichtag: alt aus, neu an","alt und neu laufen nebeneinander","Modul für Modul umstellen"]}},{"gap":{"answers":["Nutzen kommt für die anderen später"],"options":["Nutzen kommt für die anderen später","Fehler treffen sofort den ganzen Betrieb","doppelte Arbeit und Kosten","dauert lange, Schnittstellen nötig"]}}]]}'::jsonb,
  'current'
)
