insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-handel-a',
  'web_internet',
  'wi-aufruf',
  'open',
  'Die Filialseiten mit Öffnungszeiten und Angeboten sind bisher statisch. Die Geschäftsleitung fragt, was eine dynamische Website davon unterscheidet.',
  'Erläutere den Unterschied zwischen einer statischen und einer dynamischen Website.',
  'Für die volle Punktzahl müssen beide Seiten des Vergleichs erkennbar sein: statisch = feste Dateien, gleicher Inhalt; dynamisch = beim Aufruf serverseitig erzeugt, nutzer- oder eingabeabhängig.',
  2,
  '{}',
  null,
  '{"case_id":"f-a04d-handel","points":3,"criteria":[{"text":"Statisch: fertige Dateien auf dem Server, jeder Besucher sieht denselben Inhalt.","points":2,"keywords":["fertige Dateien","feste Dateien","denselben Inhalt","gleichen Inhalt"]},{"text":"Dynamisch: Die Seite wird beim Aufruf auf dem Server erzeugt, oft aus einer Datenbank; Inhalte hängen von Nutzer oder Eingabe ab.","points":2,"keywords":["beim Aufruf","erzeugt","generiert","Datenbank","serverseitig"]}],"sample_solution":"Eine statische Website besteht aus fertigen Dateien, die der Server unverändert ausliefert - alle Besucher sehen dasselbe. Eine dynamische Website wird bei jedem Aufruf von einem Programm auf dem Server erzeugt, meist aus einer Datenbank. Ihr Inhalt kann vom Nutzer oder von Eingaben abhängen und über ein Redaktionssystem gepflegt werden."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
