insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-handel-h',
  'web_internet',
  'wi-aufruf',
  'marking',
  'Für die Pflege der Filialseiten soll ein Redaktionssystem eingesetzt werden. In der englischen Produktbeschreibung steht:',
  'Markiere alle Aussagen, die sich dem Text entnehmen lassen.',
  'Je richtig entnommener Aussage 1 Punkt. Der Text beschreibt eine dynamische Website: Inhalte in der Datenbank, Seitenaufbau beim Aufruf aus Vorlage (template) und Inhalt, Pflege ohne Programmierkenntnisse - und regelmäßige Updates als Schutz vor Angriffen.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"choices":[{"text":"Beschäftigte können Texte und Bilder ohne Programmierkenntnisse ändern.","is_correct":true,"rationale":"„without programming skills“."},{"text":"Die Inhalte liegen in einer Datenbank.","is_correct":true,"rationale":"„The content is stored in a database“."},{"text":"Jede Seite liegt als fertige Datei auf dem Server.","is_correct":false,"rationale":"Im Gegenteil: Der Server baut die Seite beim Aufruf zusammen."},{"text":"Der Server erzeugt die Seite aus einer Vorlage und dem aktuellen Inhalt.","is_correct":true,"rationale":"„builds it from a template and the current content“."},{"text":"Ein CMS muss nach der Einrichtung nicht mehr aktualisiert werden.","is_correct":false,"rationale":"Der Text nennt regelmäßige Updates ausdrücklich als wichtig."},{"text":"Veraltete Versionen werden häufig angegriffen.","is_correct":true,"rationale":"„old versions are a common target for attackers“."}],"code":"A content management system\n(CMS) lets employees change\nthe texts and pictures of a\nwebsite without programming\nskills. The content is stored\nin a database. When a visitor\nopens a page, the server\nbuilds it from a template and\nthe current content. Regular\nupdates of the CMS are\nimportant, because old\nversions are a common target\nfor attackers.","case_id":"f-a04d-handel","points":4}'::jsonb,
