insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-agentur-a',
  'ki_grundlagen',
  'ki-einsatz',
  'table',
  'Eine Kundenanfrage durchläuft im Support fünf Schritte. Für den ersten Schritt ist als Muster eingetragen, wie KI unterstützen kann.',
  'Wähle für die Schritte 2 bis 5 jeweils die passende Möglichkeit der KI-Unterstützung.',
  'Je Schritt 1 Punkt. KI eignet sich für Sprache und Muster: Inhalte erkennen, klassifizieren, ähnliche Fälle finden, Texte entwerfen und zusammenfassen. Was den Kunden erreicht, prüft vorher ein Mensch.',
  2,
  '{}',
  null,
  '{"case_id":"f-a04d-agentur","points":4,"grid":[[{"text":"Prozessschritt"},{"text":"KI-Unterstützung"}],[{"text":"1. Anfrage geht per E-Mail ein"},{"text":"Anliegen aus dem Text herauslesen und als Ticket anlegen"}],[{"text":"2. Ticket erhält Kategorie und Priorität"},{"gap":{"answers":["Kategorie und Priorität vorschlagen"],"options":["Kategorie und Priorität vorschlagen","Rechnung an den Kunden erstellen","Ticket ohne Prüfung schließen"]}}],[{"text":"3. Bearbeiter sucht eine Lösung"},{"gap":{"answers":["ähnliche gelöste Tickets anzeigen"],"options":["ähnliche gelöste Tickets anzeigen","Kategorie und Priorität vorschlagen","Kundendaten löschen"]}}],[{"text":"4. Bearbeiter antwortet dem Kunden"},{"gap":{"answers":["Antwortentwurf zur Prüfung erstellen"],"options":["Antwortentwurf zur Prüfung erstellen","Antwort ungeprüft absenden","ähnliche Tickets anzeigen"]}}],[{"text":"5. Monatsbericht für die Teamleitung"},{"gap":{"answers":["häufige Probleme aus allen Tickets zusammenfassen"],"options":["häufige Probleme aus allen Tickets zusammenfassen","Antwortentwurf erstellen","Priorität vorschlagen"]}}]]}'::jsonb,
  'current'
