insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-logistik-g',
  'ki_grundlagen',
  'ki-grenzen',
  'open',
  'Die KI zur Kennzeichenerkennung wurde nur mit Bildern bei Tageslicht trainiert. Die Halle wird aber im Dreischichtbetrieb rund um die Uhr angefahren.',
  'Beschreibe ein Risiko, das sich daraus für den Einsatz der KI ergibt.',
  '2 Punkte für ein beschriebenes Risiko: Einseitige Trainingsdaten führen zu Fehlern unter Bedingungen, die das Modell nicht kennt. Deshalb mit Daten aus allen Schichten trainieren und die Ergebnisse überwachen.',
  2,
  '{}',
  null,
  '{"case_id":"f-a04d-logistik","points":2,"criteria":[{"text":"Bei Dunkelheit, Regen oder verschmutzten Kennzeichen erkennt die KI falsch oder gar nicht, weil solche Bilder im Training fehlten.","points":2,"keywords":["Dunkelheit","nachts","falsch erkannt","nicht erkannt","Trainingsdaten","Fehlerkennung"]},{"text":"Folge: LKW werden falschen Lieferungen oder Rampen zugeordnet - das Ergebnis muss von Menschen kontrolliert werden.","points":2,"keywords":["falsch zugeordnet","falsche Rampe","kontrolliert","prüfen","Verzögerung"]}],"sample_solution":"Weil Nachtaufnahmen im Training fehlten, erkennt die KI Kennzeichen bei Dunkelheit unzuverlässig. LKW werden dann falsch oder gar nicht zugeordnet; ohne Kontrolle durch Menschen entstehen Fehler und Verzögerungen an den Rampen."}'::jsonb,
  'current'
)
