insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-logistik2-a',
  'ki_grundlagen',
  'ki-einsatz',
  'open',
  'Bisher gleichen Sachbearbeiter jeden Lieferschein von Hand mit der Bestellung ab. Eine KI soll die gescannten Lieferscheine auslesen und Abweichungen melden.',
  'Beschreibe zwei Argumente, die für die KI-gestützte Prüfung der Lieferscheine sprechen.',
  'Je beschriebenem Argument 2 Punkte, verlangt sind zwei. Typisch: Zeitersparnis, weniger Fehler, Kostenreduktion, Mustererkennung, Skalierbarkeit.',
  2,
  '{}',
  null,
  '{"case_id":"f-a04d-logistik2","points":4,"criteria":[{"text":"Zeitersparnis: Lieferscheine werden in Sekunden geprüft, der Wareneingang wird schneller gebucht.","points":2,"keywords":["Zeitersparnis","schneller","Zeit","Sekunden"]},{"text":"Weniger Fehler: Abweichungen bei Menge oder Artikel werden zuverlässig erkannt, auch bei Müdigkeit in der Nachtschicht.","points":2,"keywords":["weniger Fehler","Abweichungen","zuverlässig","Fehlerquote"]},{"text":"Lernendes System: Es erkennt Muster und unterschiedliche Formulare verschiedener Lieferanten.","points":2,"keywords":["Muster","lernt","lernendes System","Formulare"]},{"text":"Kosten und Skalierbarkeit: Mehr Lieferscheine lassen sich ohne zusätzliches Personal bewältigen.","points":2,"keywords":["Kosten","skalierbar","ohne zusätzliches Personal","Personal"]}],"sample_solution":"Erstens spart die KI Zeit: Jeder Lieferschein ist in Sekunden geprüft, der Wareneingang kann schneller gebucht werden. Zweitens sinkt die Fehlerquote, weil Abweichungen bei Menge oder Artikel zuverlässig auffallen. Außerdem lernt das System die Formulare der Lieferanten und bewältigt mehr Belege ohne zusätzliches Personal."}'::jsonb,
