insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-logistik2-f',
  'datenmodellierung',
  'dm-erm',
  'table',
  'Ein Lieferschein enthält mehrere Artikel, ein Artikel kommt auf vielen Lieferscheinen vor. Im ER-Modell gibt es die Entitätstypen Lieferschein und Artikel sowie die Beziehung „enthält“.',
  'Gib für jedes Attribut an, wo es im ER-Modell eingetragen wird.',
  'Je Attribut ein halber Punkt. Menge und Chargennummer gelten für einen Artikel auf einem bestimmten Lieferschein - sie gehören an die Beziehung. Lieferdatum und Fahrer beschreiben den Lieferschein, Bezeichnung und Stückgewicht den Artikel.',
  3,
  '{}',
  null,
  '{"case_id":"f-a04d-logistik2","points":3,"grid":[[{"text":"Attribut"},{"text":"gehört zu"}],[{"text":"Lieferdatum"},{"gap":{"answers":["Lieferschein"],"options":["Lieferschein","Artikel","Beziehung „enthält“"]}}],[{"text":"Artikelbezeichnung"},{"gap":{"answers":["Artikel"],"options":["Artikel","Lieferschein","Beziehung „enthält“"]}}],[{"text":"Gelieferte Menge"},{"gap":{"answers":["Beziehung „enthält“"],"options":["Beziehung „enthält“","Lieferschein","Artikel"]}}],[{"text":"Gewicht je Stück"},{"gap":{"answers":["Artikel"],"options":["Artikel","Lieferschein","Beziehung „enthält“"]}}],[{"text":"Name des Fahrers"},{"gap":{"answers":["Lieferschein"],"options":["Lieferschein","Artikel","Beziehung „enthält“"]}}],[{"text":"Chargennummer der gelieferten Ware"},{"gap":{"answers":["Beziehung „enthält“"],"options":["Beziehung „enthält“","Lieferschein","Artikel"]}}]]}'::jsonb,
