insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-logistik2-g',
  'datenmodellierung',
  'dm-schluessel',
  'cloze',
  'Das ER-Modell aus Lieferschein (LieferscheinNr, Lieferdatum) und Artikel (ArtikelNr, Bezeichnung) mit der Beziehung „enthält“ wird in Tabellen umgesetzt. Die Zwischentabelle heißt Lieferposition.',
  'Ergänze Kardinalität und Schlüssel.',
  'Viele Artikel je Lieferschein und viele Lieferscheine je Artikel: n:m. Die LieferscheinNr identifiziert den Lieferschein. In der Zwischentabelle Lieferposition bilden die beiden Fremdschlüssel LieferscheinNr und ArtikelNr gemeinsam den Primärschlüssel.',
  2,
  '{}',
  null,
  '{"case_id":"f-a04d-logistik2","points":3,"cloze_text":"Kardinalität Lieferschein - Artikel: {0}\nPrimärschlüssel von Lieferschein: {1}\nPrimärschlüssel von Lieferposition: {2}","gaps":[{"answers":["n:m"],"options":["n:m","1:n","1:1"]},{"answers":["LieferscheinNr"],"options":["LieferscheinNr","Lieferdatum","ArtikelNr"]},{"answers":["LieferscheinNr + ArtikelNr"],"options":["LieferscheinNr + ArtikelNr","LieferscheinNr","ArtikelNr","Menge"]}]}'::jsonb,
