insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-logistik2-h',
  'multimedia_daten',
  'md-kompression',
  'open',
  'Die gescannten Lieferscheine müssen als Nachweis mehrere Jahre aufbewahrt werden. Ein Kollege schlägt vor, sie zum Platzsparen stark verlustbehaftet zu komprimieren.',
  'Erläutere, warum für die Lieferscheine eine verlustfreie Kompression gewählt werden sollte.',
  'Für die volle Punktzahl gehören zwei Gedanken zusammen: verlustfrei = exakt wiederherstellbar, und Belege müssen als Nachweis unverändert lesbar bleiben. Verlustbehaftet passt zu Fotos, Musik und Video.',
  2,
  '{}',
  null,
  '{"case_id":"f-a04d-logistik2","points":3,"criteria":[{"text":"Verlustfrei: Das Original lässt sich exakt wiederherstellen; verlustbehaftet gehen Details unwiederbringlich verloren.","points":2,"keywords":["exakt","wiederherstellen","Original","unwiederbringlich","gehen verloren"]},{"text":"Bei Belegen müssen Schrift, Zahlen und Stempel lesbar und unverändert bleiben - Artefakte könnten Mengen oder Nummern unleserlich machen.","points":2,"keywords":["lesbar","unverändert","Schrift","Nachweis","Artefakte","unleserlich"]}],"sample_solution":"Bei verlustfreier Kompression lässt sich das Original exakt wiederherstellen. Eine verlustbehaftete Kompression entfernt Details endgültig; kleine Schrift, Zahlen oder Stempel können dadurch unleserlich werden. Da die Lieferscheine als Nachweis dienen, müssen sie unverändert und lesbar bleiben."}'::jsonb,
  'current'
)
