insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a04d-systemhaus2-d',
  'web_internet',
  'wi-html',
  'marking',
  'Die Anmeldeseite des Portals wird fehlerhaft angezeigt. Du prüfst den HTML-Quelltext des Formulars.',
  'Markiere alle Zeilen, die einen Syntaxfehler enthalten.',
