insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a06-systemhaus-c',
  'kryptographie_auth',
  'kr-asymmetrisch',
  'open',
  'Das E-Mail-Programm verschlüsselt asymmetrisch. Kanzlei und Mandant besitzen je einen privaten und einen öffentlichen Schlüssel.',
  'Beschreibe anhand der Skizze, wie die Kanzlei eine E-Mail verschlüsselt und wie der Mandant sie entschlüsselt. (4 P.)',
  '2 Punkte für die Seite der Kanzlei (öffentlicher Schlüssel des Empfängers), 2 Punkte für die Seite des Mandanten (sein privater Schlüssel). Die Schlüssel der Kanzlei werden für die Verschlüsselung nicht gebraucht.',
  2,
  '{}',
  null,
  '{"diagram":{"type":"sequenz","teilnehmer":["Kanzlei","Mandant"],"nachrichten":[{"von":1,"an":0,"text":"öffentlicher Schlüssel"},{"von":0,"an":1,"text":"verschlüsselte E-Mail"}]},"case_id":"f-a06-systemhaus","points":4,"criteria":[{"text":"Die Kanzlei verschlüsselt die E-Mail mit dem öffentlichen Schlüssel des Mandanten (Empfängers)","points":2,"keywords":["öffentlichen Schlüssel","öffentlicher Schlüssel","öffentliche Schlüssel","public key"]},{"text":"Der Mandant entschlüsselt mit seinem privaten Schlüssel, den nur er besitzt","points":2,"keywords":["privaten Schlüssel","privater Schlüssel","private Schlüssel","private key"]}],"sample_solution":"Der Mandant stellt der Kanzlei seinen öffentlichen Schlüssel zur Verfügung. Die Kanzlei verschlüsselt die E-Mail mit diesem öffentlichen Schlüssel des Mandanten und sendet den Geheimtext. Der Mandant entschlüsselt mit seinem privaten Schlüssel. Weil nur er diesen Schlüssel besitzt, kann niemand sonst die E-Mail lesen."}'::jsonb,
