insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a06-handel-a',
  'datenschutz',
  'ds-grundlagen',
  'open',
  'Die Filialleitung schlägt vor, dass sich das Kassenpersonal per Fingerabdruck an den Terminals anmeldet.',
  'Begründe, warum Fingerabdruckdaten einen erhöhten Schutz benötigen, und nenne eine Rechtsgrundlage für den Datenschutz. (3 P.)',
  '2 Punkte für die Begründung (besonders schützenswerte Daten, Einwilligung nötig), 1 Punkt für die Rechtsgrundlage (DSGVO oder BDSG).',
  2,
  '{}',
  null,
  '{"case_id":"f-a06-handel","points":3,"criteria":[{"text":"Begründung: Biometrische Daten zur Identifizierung sind besonders schützenswerte personenbezogene Daten; ihre Verarbeitung ist nur ausnahmsweise erlaubt, z. B. mit ausdrücklicher Einwilligung","points":2,"keywords":["besonders schützenswert","besondere Kategorie","biometrisch","Einwilligung","Art. 9","sensibel"]},{"text":"Rechtsgrundlage: DSGVO (Art. 9) oder BDSG","points":1,"keywords":["DSGVO","BDSG","Datenschutz-Grundverordnung","Bundesdatenschutzgesetz"]}],"sample_solution":"Ein Fingerabdruck ist ein biometrisches Merkmal, das eine Person eindeutig identifiziert und sich nicht ändern lässt. Solche Daten zählen zu den besonderen Kategorien personenbezogener Daten; ihre Verarbeitung ist grundsätzlich untersagt und nur ausnahmsweise zulässig, etwa mit ausdrücklicher, freiwilliger Einwilligung. Rechtsgrundlage: DSGVO (Art. 9), ergänzt durch das BDSG."}'::jsonb,
  'current'
)
