insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a06-handel-f',
  'kryptographie_auth',
  'kr-asymmetrisch',
  'open',
  'Der Einkauf versendet Bestellungen an Lieferanten künftig digital signiert.',
  'Beschreibe anhand der Skizze, wie die digitale Signatur erstellt und wie sie geprüft wird. (4 P.)',
  '2 Punkte für das Erstellen (privater Schlüssel des Absenders), 2 Punkte für das Prüfen (öffentlicher Schlüssel des Absenders). Auch die Kurzfassung „mit dem privaten Schlüssel signieren, mit dem öffentlichen prüfen“ erhält volle Punkte.',
  2,
  '{}',
  null,
  '{"diagram":{"type":"sequenz","teilnehmer":["Einkauf","Lieferant"],"nachrichten":[{"von":0,"an":1,"text":"Zertifikat (öff. Schlüssel)"},{"von":0,"an":1,"text":"Bestellung + Signatur"}]},"case_id":"f-a06-handel","points":4,"criteria":[{"text":"Erstellen: Hashwert der Bestellung bilden und mit dem privaten Schlüssel des Einkaufs (Absenders) verschlüsseln; Bestellung und Signatur senden","points":2,"keywords":["privaten Schlüssel","privater Schlüssel","private Schlüssel","private key"]},{"text":"Prüfen: Lieferant entschlüsselt die Signatur mit dem öffentlichen Schlüssel des Einkaufs, berechnet den Hashwert neu und vergleicht","points":2,"keywords":["öffentlichen Schlüssel","öffentlicher Schlüssel","öffentliche Schlüssel","public key"]}],"sample_solution":"Der Einkauf bildet den Hashwert der Bestellung und verschlüsselt ihn mit seinem privaten Schlüssel - das ist die Signatur. Bestellung und Signatur gehen an den Lieferanten. Dieser entschlüsselt die Signatur mit dem öffentlichen Schlüssel des Einkaufs, berechnet den Hashwert der Bestellung selbst und vergleicht beide Werte. Stimmen sie überein, ist die Bestellung echt (Authentizität) und unverändert (Integrität)."}'::jsonb,
  'current'
)
