insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-systemhaus-f',
  'sla_service',
  'sla-inhalte',
  'table',
  'Für den laufenden Betrieb schließt die Kanzlei mit Kessler & Brandt einen Wartungsvertrag: Servicezeit Montag bis Freitag von 8 bis 18 Uhr, Verfügbarkeit des Dateiservers 99 % der Servicezeit je Monat. Im ersten Monat mit 21 Arbeitstagen fällt der Server innerhalb der Servicezeit insgesamt 4,2 Stunden aus.',
  'Ermittle die Kennzahlen für diesen Monat.',
  'Servicezeit: 21 × 10 h = 210 h. Zulässiger Ausfall: 210 h × 1 % = 2,1 h = 126 min. Erreicht: (210 h − 4,2 h) / 210 h = 205,8 / 210 = 0,98 = 98 %. Das SLA ist verfehlt - der Ausfall war doppelt so lang wie erlaubt.',
  2,
  '{}',
  null,
  '{"case_id":"f-a07-systemhaus","points":4,"grid":[[{"text":"Kennzahl"},{"text":"Wert"}],[{"text":"Servicezeit im Monat (in Stunden)"},{"gap":{"answers":["210"],"numeric":true,"unit":"h","rationale":"21 Tage × 10 h"}}],[{"text":"Höchstens zulässiger Ausfall (in Minuten)"},{"gap":{"answers":["126"],"numeric":true,"unit":"min","rationale":"210 h × 0,01 = 2,1 h"}}],[{"text":"Erreichte Verfügbarkeit (in Prozent)"},{"gap":{"answers":["98"],"numeric":true,"unit":"%","rationale":"(210 − 4,2) / 210"}}],[{"text":"SLA eingehalten?"},{"gap":{"answers":["nein"],"options":["nein","ja","nicht feststellbar"],"rationale":"98 % liegt unter den zugesagten 99 %."}}]]}'::jsonb,
  'current'
)
