insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-systemhaus-g',
  'change_management',
  'cm-widerstand',
  'open',
  'Zur Vorbereitung der Einführung der digitalen Akte liest die Kanzleileitung einen englischen Fachbeitrag.',
  'Benenne drei Gründe für Widerstand gegen neue Software, die der Text anführt.',
  'Je Nennung 1 Punkt, höchstens 3 Punkte. Gewertet wird nur, was im Text steht; geantwortet wird auf Deutsch und sinngemäß, nicht wörtlich übersetzt.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"code":"Employees rarely resist new software itself. What they\nresist is the uncertainty that comes with it. Some are\nafraid of losing their job when tasks are automated.\nOthers worry that they will not be able to handle the\nnew tool. Many simply do not see why a routine that has\nworked for years should be changed, and some suspect\nthat the system will be used to monitor their work.","case_id":"f-a07-systemhaus","points":3,"criteria":[{"text":"Angst, den Arbeitsplatz durch Automatisierung zu verlieren","points":1,"keywords":["Arbeitsplatz","Job","Stelle","Automatisierung"]},{"text":"Sorge, das neue Werkzeug nicht bedienen zu können","points":1,"keywords":["nicht bedienen","überfordert","Überforderung","nicht beherrschen","nicht können"]},{"text":"Fehlende Einsicht, warum Bewährtes geändert werden soll","points":1,"keywords":["Bewährtes","Routine","Gewohnheit","nicht einsehen","Einsicht"]},{"text":"Verdacht, das System diene der Überwachung der Arbeit","points":1,"keywords":["Überwachung","Kontrolle","überwachen"]},{"text":"Allgemeine Unsicherheit durch die Veränderung","points":1,"keywords":["Unsicherheit","Ungewissheit","unsicher"]}],"sample_solution":"Der Text nennt: Angst vor dem Verlust des Arbeitsplatzes durch Automatisierung, Sorge, das neue Werkzeug nicht zu beherrschen, fehlende Einsicht, warum ein bewährter Ablauf geändert werden soll, und den Verdacht, das System werde zur Überwachung der Arbeit genutzt."}'::jsonb,
  'current'
)
