insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-handel-c',
  'leistungsstoerungen',
  'ls-maengel',
  'cloze',
  'Der Fachhändler kann die beiden Scanner auch im zweiten Versuch nicht instand setzen. Grünwerk behält die Kassen und mindert den Kaufpreis. Je Kassensystem wurden 1.500 € gezahlt. Ohne Mangel ist ein System 1.600 € wert, mit dem Mangel 1.200 €.',
  'Berechne die Minderung für die beiden mangelhaften Kassensysteme.',
  'Wertverhältnis: 1.200 / 1.600 = 0,75. Geminderter Preis: 1.500 € × 0,75 = 1.125 €. Minderung je System: 1.500 € − 1.125 € = 375 €, für zwei Systeme 750 € (§ 441 Abs. 3 BGB). Die bloße Wertdifferenz von 400 € wäre falsch.',
  2,
  '{}',
  null,
  '{"case_id":"f-a07-handel","points":4,"cloze_text":"Wertverhältnis (mit Mangel / ohne Mangel): {0}\nGeminderter Preis je Kassensystem: {1} €\nMinderung je Kassensystem: {2} €\nMinderung für beide Systeme: {3} €","gaps":[{"answers":["0.75"],"numeric":true,"rationale":"1.200 / 1.600"},{"answers":["1125"],"numeric":true,"rationale":"1.500 € × 0,75"},{"answers":["375"],"numeric":true,"rationale":"1.500 € − 1.125 €"},{"answers":["750"],"numeric":true,"rationale":"2 × 375 €"}],"mono":true}'::jsonb,
  'current'
)
