insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-agentur-e',
  'change_management',
  'cm-widerstand',
  'marking',
  'In der Teamrunde stellt die Geschäftsführung das Ticketsystem vor. Du notierst die Reaktionen.',
  'Markiere alle Reaktionen, die auf Widerstand gegen die Einführung hindeuten.',
  'Widerstand zeigt sich als Widerspruch, Ausweichen, Aufregung oder Lustlosigkeit. Sachliche Fragen und die Bereitschaft zum Testen sind Zeichen von Beteiligung. Vier der sechs Reaktionen deuten auf Widerstand hin.',
  2,
  '{}',
  null,
  '{"choices":[{"text":"„Meine Kunden schreiben mir direkt, das hat immer funktioniert.“","is_correct":true,"rationale":"Offener Widerspruch gegen die Veränderung."},{"text":"„Wie sehe ich im Ticketsystem, welche Anfragen zu meinem Projekt gehören?“","is_correct":false,"rationale":"Sachliche Frage zur Nutzung - Interesse, kein Widerstand."},{"text":"Ein Projektleiter wechselt jedes Mal das Thema, sobald es um den Starttermin geht.","is_correct":true,"rationale":"Ausweichen - verbal und passiv."},{"text":"Auf dem Flur heißt es, das System diene nur dazu, Antwortzeiten zu überwachen.","is_correct":true,"rationale":"Gerüchte und Unruhe - Aufregung."},{"text":"„Ich würde gern in der Testphase mitmachen.“","is_correct":false,"rationale":"Bereitschaft zur Beteiligung."},{"text":"Zwei Kolleginnen sagen nichts und erscheinen nicht zur angesetzten Schulung.","is_correct":true,"rationale":"Rückzug und Lustlosigkeit - verdeckter Widerstand."}],"case_id":"f-a07-agentur","points":3}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
