insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-agentur-f',
  'change_management',
  'cm-widerstand',
  'open',
  null,
  'Beschreibe zwei Maßnahmen, mit denen die Agentur die Akzeptanz des Ticketsystems fördern kann.',
  'Je beschriebene Maßnahme 2 Punkte, höchstens 4 Punkte. Druck und Anordnung wären das letzte Mittel und erzeugen oft nur Scheinanpassung.',
  2,
  '{}',
  null,
  '{"case_id":"f-a07-agentur","points":4,"criteria":[{"text":"Früh informieren: zeigen, wie viele Anfragen im Postfach untergehen und was das Ticketsystem verbessert","points":2,"keywords":["informieren","kommunizieren","erklären","Nutzen","transparent"]},{"text":"Projektleiter beteiligen, z. B. Kategorien und Abläufe gemeinsam festlegen","points":2,"keywords":["beteiligen","einbeziehen","mitgestalten","gemeinsam"]},{"text":"Schulungen und Kurzanleitungen anbieten","points":2,"keywords":["Schulung","schulen","Training","Anleitung"]},{"text":"Key-User benennen, die in der Startphase Fragen beantworten","points":2,"keywords":["Key-User","Multiplikator","Ansprechpartner"]},{"text":"Regeln zur Auswertung festlegen: keine individuelle Leistungskontrolle","points":2,"keywords":["Leistungskontrolle","Überwachung","Regeln","zusichern"]},{"text":"Altes Postfach nach der Umstellung abschalten und erste Erfolge sichtbar machen","points":2,"keywords":["abschalten","Erfolge","Kennzahlen"]}],"sample_solution":"Erstens die Projektleiter beteiligen: Kategorien, Zuständigkeiten und Abläufe im Ticketsystem werden gemeinsam festgelegt, damit das System zu ihrer Arbeit passt. Zweitens schulen und begleiten: kurze Schulungen, eine Kurzanleitung und Key-User als Ansprechpartner. Weitere Möglichkeiten: den Nutzen mit Zahlen belegen, zusichern, dass keine individuelle Leistungskontrolle stattfindet."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
