insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-agentur-g',
  'change_management',
  'cm-widerstand',
  'open',
  null,
  'Erläutere einen Vorteil, den das Ticketsystem den skeptischen Projektleitern im Arbeitsalltag bringt.',
  '2 Punkte für einen erläuterten Vorteil aus Sicht der Betroffenen (Aussage plus Folge). Vorteile nur für das Unternehmen, etwa Auswertungen für die Geschäftsführung, überzeugen Skeptiker kaum.',
  2,
  '{}',
  null,
  '{"case_id":"f-a07-agentur","points":2,"criteria":[{"text":"Keine Anfrage geht verloren: Jede Anfrage hat einen Status und eine zuständige Person","points":2,"keywords":["verloren","Status","Zuständigkeit","nachverfolgen"]},{"text":"Vertretung wird einfacher: Kolleginnen und Kollegen sehen den gesamten Verlauf","points":2,"keywords":["Vertretung","Verlauf","Historie","Urlaub"]},{"text":"Weniger Rückfragen und Suchaufwand, mehr Zeit für die Projektarbeit","points":2,"keywords":["Rückfragen","Suchen","Zeit","Entlastung","Überblick"]}],"sample_solution":"Im Ticketsystem geht keine Kundenanfrage mehr unter: Jede Anfrage hat eine zuständige Person und einen sichtbaren Status. Das entlastet die Projektleiter, weil sie nicht mehr im Postfach suchen müssen und bei Urlaub oder Krankheit die Vertretung den gesamten Verlauf sieht."}'::jsonb,
