insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-logistik-a',
  'leistungsstoerungen',
  'ls-verzug',
  'open',
  null,
  'Prüfe, ob sich der Händler am 20. April im Lieferungsverzug befindet. Begründe dein Ergebnis.',
  '1 Punkt Fälligkeit, 2 Punkte Entbehrlichkeit der Mahnung mit Begründung, 1 Punkt Vertretenmüssen und Ergebnis. Das Vertrösten am Telefon ändert nichts am Verzug.',
  2,
  '{}',
  null,
  '{"case_id":"f-a07-logistik","points":4,"criteria":[{"text":"Die Lieferung ist seit dem 15. April fällig und nicht erfolgt","points":1,"keywords":["fällig","Fälligkeit","nicht geliefert"]},{"text":"Eine Mahnung ist entbehrlich, weil der Liefertermin nach dem Kalender bestimmt ist","points":2,"keywords":["Kalender","keine Mahnung","ohne Mahnung","Mahnung entbehrlich","fester Termin"]},{"text":"Der Händler hat die Verspätung zu vertreten (Verschulden wird vermutet) - er ist seit dem 16. April in Verzug","points":1,"keywords":["vertreten","Verschulden","in Verzug","16. April"]}],"sample_solution":"Ja, der Händler ist in Verzug. Die Lieferung war am 15. April fällig und ist nicht erfolgt. Eine Mahnung ist nicht nötig, weil der Termin nach dem Kalender bestimmt ist (§ 286 Abs. 2 Nr. 1 BGB). Dass der Händler die Verspätung nicht zu vertreten hätte, ist nicht ersichtlich; sein Verschulden wird vermutet. Verzug besteht daher seit dem 16. April."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
