insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-logistik-d',
  'sla_service',
  'sla-support',
  'table',
  'Für die Scanner gilt intern ein SLA. Auswirkung hoch = ganze Halle, mittel = eine Schicht oder Abteilung, niedrig = einzelne Person. Dringlichkeit hoch = die Arbeit steht still, mittel = Arbeit eingeschränkt möglich, niedrig = Ersatzgerät vorhanden.',
  'Bestimme für jede Störung die Priorität und die Reaktionszeit laut Matrix.',
  'WLAN-Ausfall: ganze Halle (hoch), Arbeit steht still (hoch) = P1, 15 min. Einzelner Scanner mit Ersatzgerät: niedrig/niedrig = P5, 24 h. Verzögerte Synchronisation in einer Schicht: mittel/mittel = P3, 4 h.',
  2,
  '{}',
  null,
  '{"table":[["Auswirkung","dringend: hoch","mittel","niedrig"],["hoch","P1: 15 min","P2: 1 h","P3: 4 h"],["mittel","P2: 1 h","P3: 4 h","P4: 8 h"],["niedrig","P3: 4 h","P4: 8 h","P5: 24 h"]],"case_id":"f-a07-logistik","points":5,"grid":[[{"text":"Störung"},{"text":"Priorität"},{"text":"Reaktionszeit"}],[{"text":"Das WLAN der neuen Halle fällt aus, kein Scanner bucht mehr, die Verladung steht."},{"gap":{"answers":["P1"],"options":["P1","P2","P3","P4","P5"]}},{"gap":{"answers":["15 min"],"options":["15 min","1 h","4 h","8 h","24 h"]}}],[{"text":"Der Scanner eines Kommissionierers ist defekt; im Schichtbüro liegen Ersatzgeräte."},{"gap":{"answers":["P5"],"options":["P5","P1","P2","P3","P4"]}},{"gap":{"answers":["24 h"],"options":["24 h","15 min","1 h","4 h","8 h"]}}],[{"text":"In der Spätschicht synchronisieren alle Scanner nur verzögert; gearbeitet wird langsamer."},{"gap":{"answers":["P3"],"options":["P3","P1","P2","P4","P5"]}},{"gap":{"answers":["4 h"],"options":["4 h","15 min","1 h","8 h","24 h"]}}]]}'::jsonb,
  'current'
)
