insert into public.ap1_questions
  (id, topic_id, subtopic_id, kind, scenario, prompt, explanation, difficulty, tags, source, data, catalog_status)
values (
  'f-a07-logistik-e',
  'change_management',
  'cm-lewin',
  'open',
  'Zur Planung der Inbetriebnahme liegt der IT-Abteilung ein englischer Text vor.',
  'Benenne die drei Einführungsstrategien, die der Text beschreibt.',
  'Je Nennung 1 Punkt. Die stufenweise Einführung Modul für Modul ist eine vierte Strategie, steht aber nicht im Text und wird hier nicht gewertet.',
  2,
  ARRAY['englisch']::text[],
  null,
  '{"code":"There is more than one way to put a new system into\noperation. With a direct cutover, the old system is\nswitched off on a fixed date and everybody starts using\nthe new one at once. In a parallel run, both systems are\nused side by side for some weeks and the results are\ncompared. A pilot introduces the new system in one\ndepartment or site first; the lessons learned there are\nused before it is rolled out to the rest of the company.","case_id":"f-a07-logistik","points":3,"criteria":[{"text":"Sofortumstellung zu einem Stichtag (direct cutover)","points":1,"keywords":["Sofortumstellung","Stichtag","Big Bang","Direktumstellung"]},{"text":"Parallelbetrieb von altem und neuem System (parallel run)","points":1,"keywords":["Parallelbetrieb","parallel","nebeneinander"]},{"text":"Pilotbetrieb in einer Abteilung oder an einem Standort (pilot)","points":1,"keywords":["Pilot","Pilotbetrieb","Pilotphase","Testbereich"]}],"sample_solution":"Der Text beschreibt die Sofortumstellung zu einem Stichtag (direct cutover), den Parallelbetrieb von altem und neuem System (parallel run) und den Pilotbetrieb in einer Abteilung oder an einem Standort, bevor alle umgestellt werden (pilot)."}'::jsonb,
  'current'
)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  kind = excluded.kind,
  scenario = excluded.scenario,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  data = excluded.data,
  catalog_status = excluded.catalog_status,
  is_active = true;

